00069 void CS::setRefinedMotionField(CodingStructure &cs)
00070 {
00071   for (CodingUnit *cu : cs.cus)
00072   {
00073     for (auto &pu : CU::traversePUs(*cu))
00074     {
00075       PredictionUnit subPu = pu;
00076       int dx, dy, x, y, num = 0;
00077       dy = std::min<int>(pu.lumaSize().height, DMVR_SUBCU_HEIGHT);
00078       dx = std::min<int>(pu.lumaSize().width, DMVR_SUBCU_WIDTH);
00079       Position puPos = pu.lumaPos();
00080       if (PU::checkDMVRCondition(pu))
00081       {
00082         for (y = puPos.y; y < (puPos.y + pu.lumaSize().height); y = y + dy)
00083         {
00084           for (x = puPos.x; x < (puPos.x + pu.lumaSize().width); x = x + dx)
00085           {
00086             subPu.UnitArea::operator=(UnitArea(pu.chromaFormat, Area(x, y, dx, dy)));
00087             subPu.mv[0] = pu.mv[0];
00088             subPu.mv[1] = pu.mv[1];
00089             subPu.mv[REF_PIC_LIST_0] += pu.mvdL0SubPu[num];
00090             subPu.mv[REF_PIC_LIST_1] -= pu.mvdL0SubPu[num];
00091             subPu.mv[REF_PIC_LIST_0].clipToStorageBitDepth();
00092             subPu.mv[REF_PIC_LIST_1].clipToStorageBitDepth();
00093             pu.mvdL0SubPu[num].setZero();
00094             num++;
00095             PU::spanMotionInfo(subPu);
00096           }
00097         }
00098       }
00099     }
00100   }
00101 }
