00152 void CU::checkConformanceILRP(Slice *slice)
00153 {
00154   const int numRefList = slice->isInterB() ? 2 : 1;
00155 
00156   int currentSubPicIdx = NOT_VALID;
00157 
00158   // derive sub-picture index for the current slice
00159   for( int subPicIdx = 0; subPicIdx < slice->getPic()->cs->sps->getNumSubPics(); subPicIdx++ )
00160   {
00161     if( slice->getPic()->cs->pps->getSubPic( subPicIdx ).getSubPicID() == slice->getSliceSubPicId() )
00162     {
00163       currentSubPicIdx = subPicIdx;
00164       break;
00165     }
00166   }
00167 
00168   CHECK( currentSubPicIdx == NOT_VALID, "Sub-picture was not found" );
00169 
00170   if( !slice->getPic()->cs->sps->getSubPicTreatedAsPicFlag( currentSubPicIdx ) )
00171   {
00172     return;
00173   }
00174 
00175   //constraint 1: The picture referred to by each active entry in RefPicList[ 0 ] or RefPicList[ 1 ] has the same subpicture layout as the current picture 
00176   bool isAllRefSameSubpicLayout = true;
00177   for (int refList = 0; refList < numRefList; refList++) // loop over l0 and l1
00178   {
00179     RefPicList  eRefPicList = (refList ? REF_PIC_LIST_1 : REF_PIC_LIST_0);
00180 
00181     for (int refIdx = 0; refIdx < slice->getNumRefIdx(eRefPicList); refIdx++)
00182     {
00183       const Picture* refPic = slice->getRefPic( eRefPicList, refIdx );
00184 
00185       if( refPic->subPictures.size() != slice->getPic()->cs->pps->getNumSubPics() )
00186       {
00187         isAllRefSameSubpicLayout = false;
00188         refList = numRefList;
00189         break;
00190       }
00191       else
00192       {
00193         for( int i = 0; i < refPic->subPictures.size(); i++ )
00194         {
00195           const SubPic& refSubPic = refPic->subPictures[i];
00196           const SubPic& curSubPic = slice->getPic()->cs->pps->getSubPic( i );
00197 
00198           if( refSubPic.getSubPicWidthInCTUs() != curSubPic.getSubPicWidthInCTUs()
00199             || refSubPic.getSubPicHeightInCTUs() != curSubPic.getSubPicHeightInCTUs()
00200             || refSubPic.getSubPicCtuTopLeftX() != curSubPic.getSubPicCtuTopLeftX()
00201             || refSubPic.getSubPicCtuTopLeftY() != curSubPic.getSubPicCtuTopLeftY()
00202             || ( refPic->layerId != slice->getPic()->layerId && refSubPic.getSubPicID() != curSubPic.getSubPicID() )
00203             || refSubPic.getTreatedAsPicFlag() != curSubPic.getTreatedAsPicFlag())
00204           {
00205             isAllRefSameSubpicLayout = false;
00206             refIdx = slice->getNumRefIdx(eRefPicList);
00207             refList = numRefList;
00208             break;
00209           }
00210         }
00211 
00212         // A picture with different sub-picture ID of the collocated sub-picture cannot be used as an active reference picture in the same layer
00213         if( refPic->layerId == slice->getPic()->layerId )
00214         {
00215           isAllRefSameSubpicLayout = isAllRefSameSubpicLayout && refPic->subPictures[currentSubPicIdx].getSubPicID() == slice->getSliceSubPicId();
00216         }
00217       }
00218     }
00219   }
00220 
00221   //constraint 2: The picture referred to by each active entry in RefPicList[ 0 ] or RefPicList[ 1 ] is an ILRP for which the value of sps_num_subpics_minus1 is equal to 0
00222   if (!isAllRefSameSubpicLayout)
00223   {
00224     for (int refList = 0; refList < numRefList; refList++) // loop over l0 and l1
00225     {
00226       RefPicList  eRefPicList = (refList ? REF_PIC_LIST_1 : REF_PIC_LIST_0);
00227       for (int refIdx = 0; refIdx < slice->getNumRefIdx(eRefPicList); refIdx++)
00228       {
00229         const Picture* refPic = slice->getRefPic( eRefPicList, refIdx );
00230         CHECK( refPic->layerId == slice->getPic()->layerId || refPic->subPictures.size() > 1, "The inter-layer reference shall contain a single subpicture or have same subpicture layout with the current picture" );
00231       }
00232     }
00233   }
00234 
00235   return;
00236 }
