00278 bool CU::isSameCtu(const CodingUnit& cu, const CodingUnit& cu2)
00279 {
00280   uint32_t ctuSizeBit = floorLog2(cu.cs->sps->getMaxCUWidth());
00281 
00282   Position pos1Ctu(cu.lumaPos().x  >> ctuSizeBit, cu.lumaPos().y  >> ctuSizeBit);
00283   Position pos2Ctu(cu2.lumaPos().x >> ctuSizeBit, cu2.lumaPos().y >> ctuSizeBit);
00284 
00285   return pos1Ctu.x == pos2Ctu.x && pos1Ctu.y == pos2Ctu.y;
00286 }
