00328 uint32_t CU::getNumPUs( const CodingUnit& cu )
00329 {
00330   uint32_t cnt = 0;
00331   PredictionUnit *pu = cu.firstPU;
00332 
00333   do
00334   {
00335     cnt++;
00336   } while( ( pu != cu.lastPU ) && ( pu = pu->next ) );
00337 
00338   return cnt;
