00346 void CU::saveMotionInHMVP( const CodingUnit& cu, const bool isToBeDone )
00347 {
00348   const PredictionUnit& pu = *cu.firstPU;
00349 
00350   if (!cu.geoFlag && !cu.affine && !isToBeDone)
00351   {
00352     MotionInfo mi = pu.getMotionInfo();
00353 
00354     mi.BcwIdx = (mi.interDir == 3) ? cu.BcwIdx : BCW_DEFAULT;
00355 
00356     const unsigned log2ParallelMergeLevel = (pu.cs->sps->getLog2ParallelMergeLevelMinus2() + 2);
00357     const unsigned xBr = pu.cu->Y().width + pu.cu->Y().x;
00358     const unsigned yBr = pu.cu->Y().height + pu.cu->Y().y;
00359     bool enableHmvp = ((xBr >> log2ParallelMergeLevel) > (pu.cu->Y().x >> log2ParallelMergeLevel)) && ((yBr >> log2ParallelMergeLevel) > (pu.cu->Y().y >> log2ParallelMergeLevel));
00360     bool enableInsertion = CU::isIBC(cu) || enableHmvp;
00361     if (enableInsertion)
00362     cu.cs->addMiToLut(CU::isIBC(cu) ? cu.cs->motionLut.lutIbc : cu.cs->motionLut.lut, mi);
00363   }
00364 }
