00366 PartSplit CU::getSplitAtDepth( const CodingUnit& cu, const unsigned depth )
00367 {
00368   if (depth >= cu.depth)
00369   {
00370     return CU_DONT_SPLIT;
00371   }
00372 
00373   const PartSplit cuSplitType = PartSplit( ( cu.splitSeries >> ( depth * SPLIT_DMULT ) ) & SPLIT_MASK );
00374 
00375   if (cuSplitType == CU_QUAD_SPLIT)
00376   {
00377     return CU_QUAD_SPLIT;
00378   }
00379 
00380   else if (cuSplitType == CU_HORZ_SPLIT)
00381   {
00382     return CU_HORZ_SPLIT;
00383   }
00384 
00385   else if (cuSplitType == CU_VERT_SPLIT)
00386   {
00387     return CU_VERT_SPLIT;
00388   }
00389 
00390   else if (cuSplitType == CU_TRIH_SPLIT)
00391   {
00392     return CU_TRIH_SPLIT;
00393   }
00394   else if (cuSplitType == CU_TRIV_SPLIT)
00395   {
00396     return CU_TRIV_SPLIT;
00397   }
00398   else
00399   {
00400     THROW("Unknown split mode");
00401     return CU_QUAD_SPLIT;
00402   }
00403 }
