00421 PartSplit CU::getISPType( const CodingUnit &cu, const ComponentID compID )
00422 {
00423   if( cu.ispMode && isLuma( compID ) )
00424   {
00425     const bool tuIsDividedInRows = CU::divideTuInRows( cu );
00426 
00427     return tuIsDividedInRows ? TU_1D_HORZ_SPLIT : TU_1D_VERT_SPLIT;
00428   }
00429   return TU_NO_ISP;
00430 }
00431 
00432 bool CU::isISPLast( const CodingUnit &cu, const CompArea &tuArea, const ComponentID compID )
00433 {
00434   PartSplit partitionType = CU::getISPType( cu, compID );
00435 
00436   Area originalArea = cu.blocks[compID];
00437   switch( partitionType )
00438   {
00439     case TU_1D_HORZ_SPLIT:
00440       return tuArea.y + tuArea.height == originalArea.y + originalArea.height;
00441     case TU_1D_VERT_SPLIT:
00442       return tuArea.x + tuArea.width == originalArea.x + originalArea.width;
00443     default:
00444       THROW( "Unknown ISP processing order type!" );
00445       return false;
00446   }
00447 }
