00454 bool CU::canUseISP( const CodingUnit &cu, const ComponentID compID )
00455 {
00456   const int width     = cu.blocks[compID].width;
00457   const int height    = cu.blocks[compID].height;
00458   const int maxTrSize = cu.cs->sps->getMaxTbSize();
00459   return CU::canUseISP( width, height, maxTrSize );
00460 }
00461 
00462 bool CU::canUseISP( const int width, const int height, const int maxTrSize )
00463 {
00464   bool  notEnoughSamplesToSplit = ( floorLog2(width) + floorLog2(height) <= ( floorLog2(MIN_TB_SIZEY) << 1 ) );
00465   bool  cuSizeLargerThanMaxTrSize = width > maxTrSize || height > maxTrSize;
00466   if ( notEnoughSamplesToSplit || cuSizeLargerThanMaxTrSize )
00467   {
00468     return false;
00469   }
00470   return true;
00471 }
00472 
00473 bool CU::canUseLfnstWithISP( const CompArea& cuArea, const ISPType ispSplitType )
00474 {
00475   if( ispSplitType == NOT_INTRA_SUBPARTITIONS )
00476   {
00477     return false;
00478   }
00479   Size tuSize = ( ispSplitType == HOR_INTRA_SUBPARTITIONS ) ? Size( cuArea.width, CU::getISPSplitDim( cuArea.width, cuArea.height, TU_1D_HORZ_SPLIT ) ) :
00480     Size( CU::getISPSplitDim( cuArea.width, cuArea.height, TU_1D_VERT_SPLIT ), cuArea.height );
00481 
00482   if( !( tuSize.width >= MIN_TB_SIZEY && tuSize.height >= MIN_TB_SIZEY ) )
00483   {
00484     return false;
00485   }
00486   return true;
00487 }
00488 
00489 bool CU::canUseLfnstWithISP( const CodingUnit& cu, const ChannelType chType )
00490 {
00491   CHECK( !isLuma( chType ), "Wrong ISP mode!" );
00492   return CU::canUseLfnstWithISP( cu.blocks[chType == CHANNEL_TYPE_LUMA ? 0 : 1], (ISPType)cu.ispMode );
00493 }
00494 
00495 uint32_t CU::getISPSplitDim( const int width, const int height, const PartSplit ispType )
00496 {
00497   bool divideTuInRows = ispType == TU_1D_HORZ_SPLIT;
00498   uint32_t splitDimensionSize, nonSplitDimensionSize, partitionSize, divShift = 2;
00499 
00500   if( divideTuInRows )
00501   {
00502     splitDimensionSize    = height;
00503     nonSplitDimensionSize = width;
00504   }
00505   else
00506   {
00507     splitDimensionSize    = width;
00508     nonSplitDimensionSize = height;
00509   }
00510 
00511   const int minNumberOfSamplesPerCu = 1 << ( ( floorLog2(MIN_TB_SIZEY) << 1 ) );
00512   const int factorToMinSamples = nonSplitDimensionSize < minNumberOfSamplesPerCu ? minNumberOfSamplesPerCu >> floorLog2(nonSplitDimensionSize) : 1;
00513   partitionSize = ( splitDimensionSize >> divShift ) < factorToMinSamples ? factorToMinSamples : ( splitDimensionSize >> divShift );
00514 
00515   CHECK( floorLog2(partitionSize) + floorLog2(nonSplitDimensionSize) < floorLog2(minNumberOfSamplesPerCu), "A partition has less than the minimum amount of samples!" );
00516   return partitionSize;
00517 }
