00519 bool CU::allLumaCBFsAreZero(const CodingUnit& cu)
00520 {
00521   if (!cu.ispMode)
00522   {
00523     return TU::getCbf(*cu.firstTU, COMPONENT_Y) == false;
00524   }
00525   else
00526   {
00527     int numTotalTUs = cu.ispMode == HOR_INTRA_SUBPARTITIONS ? cu.lheight() >> floorLog2(cu.firstTU->lheight()) : cu.lwidth() >> floorLog2(cu.firstTU->lwidth());
00528     TransformUnit* tuPtr = cu.firstTU;
00529     for (int tuIdx = 0; tuIdx < numTotalTUs; tuIdx++)
00530     {
00531       if (TU::getCbf(*tuPtr, COMPONENT_Y) == true)
00532       {
00533         return false;
00534       }
00535       tuPtr = tuPtr->next;
00536     }
00537     return true;
00538   }
00539 }
