00562 // PU tools
00563 
00564 int PU::getIntraMPMs( const PredictionUnit &pu, unsigned* mpm, const ChannelType &channelType /*= CHANNEL_TYPE_LUMA*/ )
00565 {
00566   const int numMPMs = NUM_MOST_PROBABLE_MODES;
00567   {
00568     CHECK(channelType != CHANNEL_TYPE_LUMA, "Not harmonized yet");
00569     int numCand      = -1;
00570     int leftIntraDir = PLANAR_IDX, aboveIntraDir = PLANAR_IDX;
00571 
00572     const CompArea &area = pu.block(getFirstComponentOfChannel(channelType));
00573     const Position posRT = area.topRight();
00574     const Position posLB = area.bottomLeft();
00575 
00576     // Get intra direction of left PU
00577     const PredictionUnit *puLeft = pu.cs->getPURestricted(posLB.offset(-1, 0), pu, channelType);
00578     if (puLeft && CU::isIntra(*puLeft->cu))
00579     {
00580       leftIntraDir = PU::getIntraDirLuma( *puLeft );
00581     }
00582 
00583     // Get intra direction of above PU
00584     const PredictionUnit *puAbove = pu.cs->getPURestricted(posRT.offset(0, -1), pu, channelType);
00585     if (puAbove && CU::isIntra(*puAbove->cu) && CU::isSameCtu(*pu.cu, *puAbove->cu))
00586     {
00587       aboveIntraDir = PU::getIntraDirLuma( *puAbove );
00588     }
00589 
00590     CHECK(2 >= numMPMs, "Invalid number of most probable modes");
00591 
00592     const int offset = (int)NUM_LUMA_MODE - 6;
00593     const int mod = offset + 3;
00594 
00595     mpm[0] = PLANAR_IDX;
00596     mpm[1] = DC_IDX;
00597     mpm[2] = VER_IDX;
00598     mpm[3] = HOR_IDX;
00599     mpm[4] = VER_IDX - 4;
00600     mpm[5] = VER_IDX + 4;
00601 
00602     if (leftIntraDir == aboveIntraDir)
00603     {
00604       numCand = 1;
00605       if (leftIntraDir > DC_IDX)
00606       {
00607         mpm[0] = PLANAR_IDX;
00608         mpm[1] = leftIntraDir;
00609         mpm[2] = ((leftIntraDir + offset) % mod) + 2;
00610         mpm[3] = ((leftIntraDir - 1) % mod) + 2;
00611         mpm[4] = ((leftIntraDir + offset - 1) % mod) + 2;
00612         mpm[5] = (leftIntraDir % mod) + 2;
00613       }
00614     }
00615     else   // L!=A
00616     {
00617       numCand            = 2;
00618       int maxCandModeIdx = mpm[0] > mpm[1] ? 0 : 1;
00619 
00620       if ((leftIntraDir > DC_IDX) && (aboveIntraDir > DC_IDX))
00621       {
00622         mpm[0]             = PLANAR_IDX;
00623         mpm[1]             = leftIntraDir;
00624         mpm[2]             = aboveIntraDir;
00625         maxCandModeIdx     = mpm[1] > mpm[2] ? 1 : 2;
00626         int minCandModeIdx = mpm[1] > mpm[2] ? 2 : 1;
00627         if (mpm[maxCandModeIdx] - mpm[minCandModeIdx] == 1)
00628         {
00629           mpm[3] = ((mpm[minCandModeIdx] + offset) % mod) + 2;
00630           mpm[4] = ((mpm[maxCandModeIdx] - 1) % mod) + 2;
00631           mpm[5] = ((mpm[minCandModeIdx] + offset - 1) % mod) + 2;
00632         }
00633         else if (mpm[maxCandModeIdx] - mpm[minCandModeIdx] >= 62)
00634         {
00635           mpm[3] = ((mpm[minCandModeIdx] - 1) % mod) + 2;
00636           mpm[4] = ((mpm[maxCandModeIdx] + offset) % mod) + 2;
00637           mpm[5] = (mpm[minCandModeIdx] % mod) + 2;
00638         }
00639         else if (mpm[maxCandModeIdx] - mpm[minCandModeIdx] == 2)
00640         {
00641           mpm[3] = ((mpm[minCandModeIdx] - 1) % mod) + 2;
00642           mpm[4] = ((mpm[minCandModeIdx] + offset) % mod) + 2;
00643           mpm[5] = ((mpm[maxCandModeIdx] - 1) % mod) + 2;
00644         }
00645         else
00646         {
00647           mpm[3] = ((mpm[minCandModeIdx] + offset) % mod) + 2;
00648           mpm[4] = ((mpm[minCandModeIdx] - 1) % mod) + 2;
00649           mpm[5] = ((mpm[maxCandModeIdx] + offset) % mod) + 2;
00650         }
00651       }
00652       else if (leftIntraDir + aboveIntraDir >= 2)
00653       {
00654         mpm[0]         = PLANAR_IDX;
00655         mpm[1]         = (leftIntraDir < aboveIntraDir) ? aboveIntraDir : leftIntraDir;
00656         maxCandModeIdx = 1;
00657         mpm[2]         = ((mpm[maxCandModeIdx] + offset) % mod) + 2;
00658         mpm[3]         = ((mpm[maxCandModeIdx] - 1) % mod) + 2;
00659         mpm[4]         = ((mpm[maxCandModeIdx] + offset - 1) % mod) + 2;
00660         mpm[5]         = (mpm[maxCandModeIdx] % mod) + 2;
00661       }
00662     }
00663     for (int i = 0; i < numMPMs; i++)
00664     {
00665       CHECK(mpm[i] >= NUM_LUMA_MODE, "Invalid MPM");
00666     }
00667     CHECK(numCand == 0, "No candidates found");
00668     return numCand;
00669   }
00670 }
