00672 bool PU::isMIP(const PredictionUnit &pu, const ChannelType &chType)
00673 {
00674   if (chType == CHANNEL_TYPE_LUMA)
00675   {
00676     // Default case if chType is omitted.
00677     return pu.cu->mipFlag;
00678   }
00679   else
00680   {
00681     return isDMChromaMIP(pu) && (pu.intraDir[CHANNEL_TYPE_CHROMA] == DM_CHROMA_IDX);
00682   }
00683 }
00684 
00685 bool PU::isDMChromaMIP(const PredictionUnit &pu)
00686 {
