00690 uint32_t PU::getIntraDirLuma( const PredictionUnit &pu )
00691 {
00692   if (isMIP(pu))
00693   {
00694     return PLANAR_IDX;
00695   }
00696   else
00697   {
00698     return pu.intraDir[CHANNEL_TYPE_LUMA];
00699   }
00700 }
