00702 
00703 void PU::getIntraChromaCandModes( const PredictionUnit &pu, unsigned modeList[NUM_CHROMA_MODE] )
00704 {
00705   modeList[0] = PLANAR_IDX;
00706   modeList[1] = VER_IDX;
00707   modeList[2] = HOR_IDX;
00708   modeList[3] = DC_IDX;
00709   modeList[4] = LM_CHROMA_IDX;
00710   modeList[5] = MDLM_L_IDX;
00711   modeList[6] = MDLM_T_IDX;
00712   modeList[7] = DM_CHROMA_IDX;
00713 
00714   // If Direct Mode is MIP, mode cannot be already in the list.
00715   if (isDMChromaMIP(pu))
00716   {
00717     return;
00718   }
00719 
00720   const uint32_t lumaMode = getCoLocatedIntraLumaMode(pu);
00721   for (int i = 0; i < 4; i++)
00722   {
00723     if (lumaMode == modeList[i])
00724     {
00725       modeList[i] = VDIA_IDX;
00726       break;
00727     }
00728   }
00729 }
