00775 const PredictionUnit &PU::getCoLocatedLumaPU(const PredictionUnit &pu)
00776 {
00777   Position              topLeftPos = pu.blocks[pu.chType].lumaPos();
00778   Position              refPos     = topLeftPos.offset(pu.blocks[pu.chType].lumaSize().width  >> 1,
00779                                                        pu.blocks[pu.chType].lumaSize().height >> 1);
00780   const PredictionUnit &lumaPU     = pu.cu->isSepTree() ? *pu.cs->picture->cs->getPU(refPos, CHANNEL_TYPE_LUMA)
00781                                                         : *pu.cs->getPU(topLeftPos, CHANNEL_TYPE_LUMA);
00782 
00783   return lumaPU;
00784 }
