00790 
00791 int PU::getWideAngle( const TransformUnit &tu, const uint32_t dirMode, const ComponentID compID )
00792 {
00793   //This function returns a wide angle index taking into account that the values 0 and 1 are reserved 
00794   //for Planar and DC respectively, as defined in the Spec. Text.
00795   if( dirMode < 2 )
00796   {
00797     return ( int ) dirMode;
00798   }
00799 
00800   const CompArea&  area         = tu.cu->ispMode && isLuma(compID) ? tu.cu->blocks[compID] : tu.blocks[ compID ];
00801   int              width        = area.width;
00802   int              height       = area.height;
00803   int              modeShift[ ] = { 0, 6, 10, 12, 14, 15 };
00804   int              deltaSize    = abs( floorLog2( width ) - floorLog2( height ) );
00805   int              predMode     = dirMode;
00806 
00807   if( width > height && dirMode < 2 + modeShift[ deltaSize ] )
00808   {
00809     predMode += ( VDIA_IDX - 1 );
00810   }
00811   else if( height > width && predMode > VDIA_IDX - modeShift[ deltaSize ] )
00812   {
00813     predMode -= ( VDIA_IDX + 1 );
00814   }
00815 
00816   return predMode;
00817 }
00818 
00819 bool PU::addMergeHMVPCand(const CodingStructure &cs, MergeCtx &mrgCtx, const int &mrgCandIdx,
00820                           const uint32_t maxNumMergeCandMin1, int &cnt, const bool isAvailableA1,
00821                           const MotionInfo miLeft, const bool isAvailableB1, const MotionInfo miAbove,
00822                           const bool ibcFlag, const bool isGt4x4)
00823 {
00824   const Slice& slice = *cs.slice;
00825   MotionInfo miNeighbor;
00826 
00827   auto &lut = ibcFlag ? cs.motionLut.lutIbc : cs.motionLut.lut;
00828   int num_avai_candInLUT = (int)lut.size();
00829 
00830   for (int mrgIdx = 1; mrgIdx <= num_avai_candInLUT; mrgIdx++)
00831   {
00832     miNeighbor = lut[num_avai_candInLUT - mrgIdx];
00833 
00834     if ( mrgIdx > 2 || ((mrgIdx > 1 || !isGt4x4) && ibcFlag)
00835       || ((!isAvailableA1 || (miLeft != miNeighbor)) && (!isAvailableB1 || (miAbove != miNeighbor))) )
00836     {
00837       mrgCtx.interDirNeighbours[cnt] = miNeighbor.interDir;
00838       mrgCtx.useAltHpelIf      [cnt] = !ibcFlag && miNeighbor.useAltHpelIf;
00839       mrgCtx.BcwIdx            [cnt] = (miNeighbor.interDir == 3) ? miNeighbor.BcwIdx : BCW_DEFAULT;
00840 
00841       mrgCtx.mvFieldNeighbours[cnt << 1].setMvField(miNeighbor.mv[0], miNeighbor.refIdx[0]);
00842       if (slice.isInterB())
00843       {
00844         mrgCtx.mvFieldNeighbours[(cnt << 1) + 1].setMvField(miNeighbor.mv[1], miNeighbor.refIdx[1]);
00845       }
00846 
00847       if (mrgCandIdx == cnt)
00848       {
00849         return true;
00850       }
00851       cnt ++;
00852 
00853       if (cnt  == maxNumMergeCandMin1)
00854       {
00855         break;
00856       }
00857     }
00858   }
00859 
00860   if (cnt < maxNumMergeCandMin1)
00861   {
00862     mrgCtx.useAltHpelIf[cnt] = false;
00863   }
00864 
00865   return false;
00866 }
00867 
00868 void PU::getIBCMergeCandidates(const PredictionUnit &pu, MergeCtx& mrgCtx, const int& mrgCandIdx)
00869 {
00870   const CodingStructure &cs = *pu.cs;
00871   const uint32_t maxNumMergeCand = pu.cs->sps->getMaxNumIBCMergeCand();
00872   for (uint32_t ui = 0; ui < maxNumMergeCand; ++ui)
00873   {
00874     mrgCtx.BcwIdx[ui] = BCW_DEFAULT;
00875     mrgCtx.interDirNeighbours[ui] = 0;
00876     mrgCtx.mrgTypeNeighbours[ui] = MRG_TYPE_IBC;
00877     mrgCtx.mvFieldNeighbours[ui * 2].refIdx = NOT_VALID;
00878     mrgCtx.mvFieldNeighbours[ui * 2 + 1].refIdx = NOT_VALID;
00879     mrgCtx.useAltHpelIf[ui] = false;
00880   }
00881 
00882   mrgCtx.numValidMergeCand = maxNumMergeCand;
00883   // compute the location of the current PU
00884 
00885   int cnt = 0;
00886 
00887   const Position posRT = pu.Y().topRight();
00888   const Position posLB = pu.Y().bottomLeft();
00889 
00890   MotionInfo miAbove, miLeft, miAboveLeft, miAboveRight, miBelowLeft;
00891 
00892   //left
00893   const PredictionUnit* puLeft = cs.getPURestricted(posLB.offset(-1, 0), pu, pu.chType);
00894   bool isGt4x4 = pu.lwidth() * pu.lheight() > 16;
00895   const bool isAvailableA1 = puLeft && pu.cu != puLeft->cu && CU::isIBC(*puLeft->cu);
00896   if (isGt4x4 && isAvailableA1)
00897   {
00898     miLeft = puLeft->getMotionInfo(posLB.offset(-1, 0));
00899 
00900     // get Inter Dir
00901     mrgCtx.interDirNeighbours[cnt] = miLeft.interDir;
00902     // get Mv from Left
00903     mrgCtx.mvFieldNeighbours[cnt << 1].setMvField(miLeft.mv[0], miLeft.refIdx[0]);
00904     if (mrgCandIdx == cnt)
00905     {
00906       return;
00907     }
00908     cnt++;
00909   }
00910 
00911   // early termination
00912   if (cnt == maxNumMergeCand)
00913   {
00914     return;
00915   }
00916 
00917   // above
00918   const PredictionUnit *puAbove = cs.getPURestricted(posRT.offset(0, -1), pu, pu.chType);
00919   bool isAvailableB1 = puAbove && pu.cu != puAbove->cu && CU::isIBC(*puAbove->cu);
00920   if (isGt4x4 && isAvailableB1)
00921   {
00922     miAbove = puAbove->getMotionInfo(posRT.offset(0, -1));
00923 
00924     if (!isAvailableA1 || (miAbove != miLeft))
00925     {
00926       // get Inter Dir
00927       mrgCtx.interDirNeighbours[cnt] = miAbove.interDir;
00928       // get Mv from Above
00929       mrgCtx.mvFieldNeighbours[cnt << 1].setMvField(miAbove.mv[0], miAbove.refIdx[0]);
00930       if (mrgCandIdx == cnt)
00931       {
00932         return;
00933       }
00934 
00935       cnt++;
00936     }
00937   }
00938 
00939   // early termination
00940   if (cnt == maxNumMergeCand)
00941   {
00942     return;
00943   }
00944 
00945   if (cnt != maxNumMergeCand)
00946   {
00947     bool bFound = addMergeHMVPCand(cs, mrgCtx, mrgCandIdx, maxNumMergeCand, cnt, isAvailableA1, miLeft, isAvailableB1,
00948                                    miAbove, true, isGt4x4);
00949 
00950     if (bFound)
00951     {
00952       return;
00953     }
00954   }
00955 
00956     while (cnt < maxNumMergeCand)
00957     {
00958       mrgCtx.mvFieldNeighbours[cnt * 2].setMvField(Mv(0, 0), MAX_NUM_REF);
00959       mrgCtx.interDirNeighbours[cnt] = 1;
00960       if (mrgCandIdx == cnt)
00961       {
00962         return;
00963       }
00964       cnt++;
00965     }
00966 
00967   mrgCtx.numValidMergeCand = cnt;
00968 }
00969 
00970 void PU::getInterMergeCandidates( const PredictionUnit &pu, MergeCtx& mrgCtx,
00971                                  int mmvdList,
00972                                  const int& mrgCandIdx )
00973 {
00974   const unsigned plevel = pu.cs->sps->getLog2ParallelMergeLevelMinus2() + 2;
00975   const CodingStructure &cs  = *pu.cs;
00976   const Slice &slice         = *pu.cs->slice;
00977   const uint32_t maxNumMergeCand = pu.cs->sps->getMaxNumMergeCand();
00978   CHECK (maxNumMergeCand > MRG_MAX_NUM_CANDS, "selected maximum number of merge candidate exceeds global limit");
00979   for (uint32_t ui = 0; ui < maxNumMergeCand; ++ui)
00980   {
00981     mrgCtx.BcwIdx[ui] = BCW_DEFAULT;
00982     mrgCtx.interDirNeighbours[ui] = 0;
00983     mrgCtx.mrgTypeNeighbours [ui] = MRG_TYPE_DEFAULT_N;
00984     mrgCtx.mvFieldNeighbours[(ui << 1)    ].refIdx = NOT_VALID;
00985     mrgCtx.mvFieldNeighbours[(ui << 1) + 1].refIdx = NOT_VALID;
00986     mrgCtx.useAltHpelIf[ui] = false;
00987   }
00988 
00989   mrgCtx.numValidMergeCand = maxNumMergeCand;
00990   // compute the location of the current PU
00991 
00992   int cnt = 0;
00993 
00994   const Position posLT = pu.Y().topLeft();
00995   const Position posRT = pu.Y().topRight();
00996   const Position posLB = pu.Y().bottomLeft();
00997   MotionInfo miAbove, miLeft, miAboveLeft, miAboveRight, miBelowLeft;
00998 
00999   // above
01000   const PredictionUnit *puAbove = cs.getPURestricted(posRT.offset(0, -1), pu, pu.chType);
01001 
01002   bool isAvailableB1 = puAbove && isDiffMER(pu.lumaPos(), posRT.offset(0, -1), plevel) && pu.cu != puAbove->cu && CU::isInter(*puAbove->cu);
01003 
01004   if (isAvailableB1)
01005   {
01006     miAbove = puAbove->getMotionInfo(posRT.offset(0, -1));
01007 
01008     // get Inter Dir
01009     mrgCtx.interDirNeighbours[cnt] = miAbove.interDir;
01010     mrgCtx.useAltHpelIf[cnt] = miAbove.useAltHpelIf;
01011     // get Mv from Above
01012     mrgCtx.BcwIdx[cnt] = (mrgCtx.interDirNeighbours[cnt] == 3) ? puAbove->cu->BcwIdx : BCW_DEFAULT;
01013     mrgCtx.mvFieldNeighbours[cnt << 1].setMvField(miAbove.mv[0], miAbove.refIdx[0]);
01014 
01015     if (slice.isInterB())
01016     {
01017       mrgCtx.mvFieldNeighbours[(cnt << 1) + 1].setMvField(miAbove.mv[1], miAbove.refIdx[1]);
01018     }
01019     if (mrgCandIdx == cnt)
01020     {
01021       return;
01022     }
01023 
01024     cnt++;
01025   }
01026 
01027   // early termination
01028   if (cnt == maxNumMergeCand)
01029   {
01030     return;
01031   }
01032 
01033   //left
01034   const PredictionUnit* puLeft = cs.getPURestricted(posLB.offset(-1, 0), pu, pu.chType);
01035 
01036   const bool isAvailableA1 = puLeft && isDiffMER(pu.lumaPos(), posLB.offset(-1, 0), plevel) && pu.cu != puLeft->cu && CU::isInter(*puLeft->cu);
01037 
01038   if (isAvailableA1)
01039   {
01040     miLeft = puLeft->getMotionInfo(posLB.offset(-1, 0));
01041 
01042     if (!isAvailableB1 || (miAbove != miLeft))
01043     {
01044       // get Inter Dir
01045       mrgCtx.interDirNeighbours[cnt] = miLeft.interDir;
01046       mrgCtx.useAltHpelIf[cnt] = miLeft.useAltHpelIf;
01047       mrgCtx.BcwIdx[cnt] = (mrgCtx.interDirNeighbours[cnt] == 3) ? puLeft->cu->BcwIdx : BCW_DEFAULT;
01048       // get Mv from Left
01049       mrgCtx.mvFieldNeighbours[cnt << 1].setMvField(miLeft.mv[0], miLeft.refIdx[0]);
01050 
01051       if (slice.isInterB())
01052       {
01053         mrgCtx.mvFieldNeighbours[(cnt << 1) + 1].setMvField(miLeft.mv[1], miLeft.refIdx[1]);
01054       }
01055       if (mrgCandIdx == cnt)
01056       {
01057         return;
01058       }
01059 
01060       cnt++;
01061     }
01062   }
01063 
01064   // early termination
01065   if( cnt == maxNumMergeCand )
01066   {
01067     return;
01068   }
01069 
01070   // above right
01071   const PredictionUnit *puAboveRight = cs.getPURestricted( posRT.offset( 1, -1 ), pu, pu.chType );
01072 
01073   bool isAvailableB0 = puAboveRight && isDiffMER( pu.lumaPos(), posRT.offset(1, -1), plevel) && CU::isInter( *puAboveRight->cu );
01074 
01075   if( isAvailableB0 )
01076   {
01077     miAboveRight = puAboveRight->getMotionInfo( posRT.offset( 1, -1 ) );
01078 
01079     if( !isAvailableB1 || ( miAbove != miAboveRight ) )
01080     {
01081 
01082       // get Inter Dir
01083       mrgCtx.interDirNeighbours[cnt] = miAboveRight.interDir;
01084       mrgCtx.useAltHpelIf[cnt] = miAboveRight.useAltHpelIf;
01085       // get Mv from Above-right
01086       mrgCtx.BcwIdx[cnt] = (mrgCtx.interDirNeighbours[cnt] == 3) ? puAboveRight->cu->BcwIdx : BCW_DEFAULT;
01087       mrgCtx.mvFieldNeighbours[cnt << 1].setMvField( miAboveRight.mv[0], miAboveRight.refIdx[0] );
01088 
01089       if( slice.isInterB() )
01090       {
01091         mrgCtx.mvFieldNeighbours[( cnt << 1 ) + 1].setMvField( miAboveRight.mv[1], miAboveRight.refIdx[1] );
01092       }
01093 
01094       if (mrgCandIdx == cnt)
01095       {
01096         return;
01097       }
01098 
01099       cnt++;
01100     }
01101   }
01102   // early termination
01103   if( cnt == maxNumMergeCand )
01104   {
01105     return;
01106   }
01107 
01108   //left bottom
01109   const PredictionUnit *puLeftBottom = cs.getPURestricted( posLB.offset( -1, 1 ), pu, pu.chType );
01110 
01111   bool isAvailableA0 = puLeftBottom && isDiffMER( pu.lumaPos(), posLB.offset(-1, 1), plevel) && CU::isInter( *puLeftBottom->cu );
01112 
01113   if( isAvailableA0 )
01114   {
01115     miBelowLeft = puLeftBottom->getMotionInfo( posLB.offset( -1, 1 ) );
01116 
01117     if( !isAvailableA1 || ( miBelowLeft != miLeft ) )
01118     {
01119       // get Inter Dir
01120       mrgCtx.interDirNeighbours[cnt] = miBelowLeft.interDir;
01121       mrgCtx.useAltHpelIf[cnt] = miBelowLeft.useAltHpelIf;
01122       mrgCtx.BcwIdx[cnt] = (mrgCtx.interDirNeighbours[cnt] == 3) ? puLeftBottom->cu->BcwIdx : BCW_DEFAULT;
01123       // get Mv from Bottom-Left
01124       mrgCtx.mvFieldNeighbours[cnt << 1].setMvField( miBelowLeft.mv[0], miBelowLeft.refIdx[0] );
01125 
01126       if( slice.isInterB() )
01127       {
01128         mrgCtx.mvFieldNeighbours[( cnt << 1 ) + 1].setMvField( miBelowLeft.mv[1], miBelowLeft.refIdx[1] );
01129       }
01130 
01131       if (mrgCandIdx == cnt)
01132       {
01133         return;
01134       }
01135 
01136       cnt++;
01137     }
01138   }
01139   // early termination
01140   if( cnt == maxNumMergeCand )
01141   {
01142     return;
01143   }
01144 
01145   // above left
01146   if ( cnt < 4 )
01147   {
01148     const PredictionUnit *puAboveLeft = cs.getPURestricted( posLT.offset( -1, -1 ), pu, pu.chType );
01149 
01150     bool isAvailableB2 = puAboveLeft && isDiffMER( pu.lumaPos(), posLT.offset(-1, -1), plevel ) && CU::isInter( *puAboveLeft->cu );
01151 
01152     if( isAvailableB2 )
01153     {
01154       miAboveLeft = puAboveLeft->getMotionInfo( posLT.offset( -1, -1 ) );
01155 
01156       if( ( !isAvailableA1 || ( miLeft != miAboveLeft ) ) && ( !isAvailableB1 || ( miAbove != miAboveLeft ) ) )
01157       {
01158 
01159         // get Inter Dir
01160         mrgCtx.interDirNeighbours[cnt] = miAboveLeft.interDir;
01161         mrgCtx.useAltHpelIf[cnt] = miAboveLeft.useAltHpelIf;
01162         mrgCtx.BcwIdx[cnt] = (mrgCtx.interDirNeighbours[cnt] == 3) ? puAboveLeft->cu->BcwIdx : BCW_DEFAULT;
01163         // get Mv from Above-Left
01164         mrgCtx.mvFieldNeighbours[cnt << 1].setMvField( miAboveLeft.mv[0], miAboveLeft.refIdx[0] );
01165 
01166         if( slice.isInterB() )
01167         {
01168           mrgCtx.mvFieldNeighbours[( cnt << 1 ) + 1].setMvField( miAboveLeft.mv[1], miAboveLeft.refIdx[1] );
01169         }
01170 
01171         if (mrgCandIdx == cnt)
01172         {
01173           return;
01174         }
01175 
01176         cnt++;
01177       }
01178     }
01179   }
01180   // early termination
01181   if (cnt == maxNumMergeCand)
01182   {
01183     return;
01184   }
01185 
01186   if (slice.getPicHeader()->getEnableTMVPFlag() && (pu.lumaSize().width + pu.lumaSize().height > 12))
01187   {
01188     //>> MTK colocated-RightBottom
01189     // offset the pos to be sure to "point" to the same position the uiAbsPartIdx would've pointed to
01190     Position posRB = pu.Y().bottomRight().offset( -3, -3 );
01191     const PreCalcValues& pcv = *cs.pcv;
01192 
01193     Position posC0;
01194     Position posC1 = pu.Y().center();
01195     bool C0Avail = false;
01196     bool boundaryCond = ((posRB.x + pcv.minCUWidth) < pcv.lumaWidth) && ((posRB.y + pcv.minCUHeight) < pcv.lumaHeight);
01197     const SubPic& curSubPic = pu.cs->slice->getPPS()->getSubPicFromPos(pu.lumaPos());
01198     if (curSubPic.getTreatedAsPicFlag())
01199     {
01200       boundaryCond = ((posRB.x + pcv.minCUWidth) <= curSubPic.getSubPicRight() &&
01201                       (posRB.y + pcv.minCUHeight) <= curSubPic.getSubPicBottom());
01202     }
01203     if (boundaryCond)
01204     {
01205       int posYInCtu = posRB.y & pcv.maxCUHeightMask;
01206       if (posYInCtu + 4 < pcv.maxCUHeight)
01207       {
01208         posC0 = posRB.offset(4, 4);
01209         C0Avail = true;
01210       }
01211     }
01212 
01213     Mv        cColMv;
01214     int       iRefIdx     = 0;
01215     int       dir         = 0;
01216     unsigned  uiArrayAddr = cnt;
01217     bool      bExistMV    = ( C0Avail && getColocatedMVP(pu, REF_PIC_LIST_0, posC0, cColMv, iRefIdx, false ) )
01218                               || getColocatedMVP( pu, REF_PIC_LIST_0, posC1, cColMv, iRefIdx, false );
01219     if (bExistMV)
01220     {
01221       dir     |= 1;
01222       mrgCtx.mvFieldNeighbours[2 * uiArrayAddr].setMvField(cColMv, iRefIdx);
01223     }
01224 
01225     if (slice.isInterB())
01226     {
01227       bExistMV = ( C0Avail && getColocatedMVP(pu, REF_PIC_LIST_1, posC0, cColMv, iRefIdx, false ) )
01228                    || getColocatedMVP( pu, REF_PIC_LIST_1, posC1, cColMv, iRefIdx, false );
01229       if (bExistMV)
01230       {
01231         dir     |= 2;
01232         mrgCtx.mvFieldNeighbours[2 * uiArrayAddr + 1].setMvField(cColMv, iRefIdx);
01233       }
01234     }
01235 
01236     if( dir != 0 )
01237     {
01238       bool addTMvp = true;
01239       if( addTMvp )
01240       {
01241         mrgCtx.interDirNeighbours[uiArrayAddr] = dir;
01242         mrgCtx.BcwIdx[uiArrayAddr] = BCW_DEFAULT;
01243         mrgCtx.useAltHpelIf[uiArrayAddr] = false;
01244         if (mrgCandIdx == cnt)
01245         {
01246           return;
01247         }
01248 
01249         cnt++;
01250       }
01251     }
01252   }
01253 
01254   // early termination
01255   if (cnt == maxNumMergeCand)
01256   {
01257     return;
01258   }
01259 
01260   int maxNumMergeCandMin1 = maxNumMergeCand - 1;
01261   if (cnt != maxNumMergeCandMin1)
01262   {
01263     bool isGt4x4 = true;
01264     bool bFound  = addMergeHMVPCand(cs, mrgCtx, mrgCandIdx, maxNumMergeCandMin1, cnt, isAvailableA1, miLeft,
01265                                    isAvailableB1, miAbove, CU::isIBC(*pu.cu), isGt4x4);
01266 
01267     if (bFound)
01268     {
01269       return;
01270     }
01271   }
01272 
01273   // pairwise-average candidates
01274   {
01275     if (cnt > 1 && cnt < maxNumMergeCand)
01276     {
01277       mrgCtx.mvFieldNeighbours[cnt * 2].setMvField( Mv( 0, 0 ), NOT_VALID );
01278       mrgCtx.mvFieldNeighbours[cnt * 2 + 1].setMvField( Mv( 0, 0 ), NOT_VALID );
01279       // calculate average MV for L0 and L1 seperately
01280       unsigned char interDir = 0;
01281 
01282       mrgCtx.useAltHpelIf[cnt] = (mrgCtx.useAltHpelIf[0] == mrgCtx.useAltHpelIf[1]) ? mrgCtx.useAltHpelIf[0] : false;
01283       for( int refListId = 0; refListId < (slice.isInterB() ? 2 : 1); refListId++ )
01284       {
01285         const short refIdxI = mrgCtx.mvFieldNeighbours[0 * 2 + refListId].refIdx;
01286         const short refIdxJ = mrgCtx.mvFieldNeighbours[1 * 2 + refListId].refIdx;
01287 
01288         // both MVs are invalid, skip
01289         if( (refIdxI == NOT_VALID) && (refIdxJ == NOT_VALID) )
01290         {
01291           continue;
01292         }
01293 
01294         interDir += 1 << refListId;
01295         // both MVs are valid, average these two MVs
01296         if( (refIdxI != NOT_VALID) && (refIdxJ != NOT_VALID) )
01297         {
01298           const Mv& MvI = mrgCtx.mvFieldNeighbours[0 * 2 + refListId].mv;
01299           const Mv& MvJ = mrgCtx.mvFieldNeighbours[1 * 2 + refListId].mv;
01300 
01301           // average two MVs
01302           Mv avgMv = MvI;
01303           avgMv += MvJ;
01304           roundAffineMv(avgMv.hor, avgMv.ver, 1);
01305 
01306           mrgCtx.mvFieldNeighbours[cnt * 2 + refListId].setMvField( avgMv, refIdxI );
01307         }
01308         // only one MV is valid, take the only one MV
01309         else if( refIdxI != NOT_VALID )
01310         {
01311           Mv singleMv = mrgCtx.mvFieldNeighbours[0 * 2 + refListId].mv;
01312           mrgCtx.mvFieldNeighbours[cnt * 2 + refListId].setMvField( singleMv, refIdxI );
01313         }
01314         else if( refIdxJ != NOT_VALID )
01315         {
01316           Mv singleMv = mrgCtx.mvFieldNeighbours[1 * 2 + refListId].mv;
01317           mrgCtx.mvFieldNeighbours[cnt * 2 + refListId].setMvField( singleMv, refIdxJ );
01318         }
01319       }
01320 
01321       mrgCtx.interDirNeighbours[cnt] = interDir;
01322       if( interDir > 0 )
01323       {
01324         cnt++;
01325       }
01326     }
01327 
01328     // early termination
01329     if( cnt == maxNumMergeCand )
01330     {
01331       return;
01332     }
01333   }
01334 
01335   uint32_t uiArrayAddr = cnt;
01336 
01337   int iNumRefIdx = slice.isInterB() ? std::min(slice.getNumRefIdx(REF_PIC_LIST_0), slice.getNumRefIdx(REF_PIC_LIST_1)) : slice.getNumRefIdx(REF_PIC_LIST_0);
01338 
01339   int r = 0;
01340   int refcnt = 0;
01341   while (uiArrayAddr < maxNumMergeCand)
01342   {
01343     mrgCtx.interDirNeighbours [uiArrayAddr     ] = 1;
01344     mrgCtx.BcwIdx             [uiArrayAddr     ] = BCW_DEFAULT;
01345     mrgCtx.mvFieldNeighbours  [uiArrayAddr << 1].setMvField(Mv(0, 0), r);
01346     mrgCtx.useAltHpelIf[uiArrayAddr] = false;
01347 
01348     if (slice.isInterB())
01349     {
01350       mrgCtx.interDirNeighbours [ uiArrayAddr          ] = 3;
01351       mrgCtx.mvFieldNeighbours  [(uiArrayAddr << 1) + 1].setMvField(Mv(0, 0), r);
01352     }
01353 
01354     if ( mrgCtx.interDirNeighbours[uiArrayAddr] == 1 && pu.cs->slice->getRefPic(REF_PIC_LIST_0, mrgCtx.mvFieldNeighbours[uiArrayAddr << 1].refIdx)->getPOC() == pu.cs->slice->getPOC())
01355     {
01356       mrgCtx.mrgTypeNeighbours[uiArrayAddr] = MRG_TYPE_IBC;
01357     }
01358 
01359     uiArrayAddr++;
01360 
01361     if (refcnt == iNumRefIdx - 1)
01362     {
01363       r = 0;
01364     }
01365     else
01366     {
01367       ++r;
01368       ++refcnt;
01369     }
01370   }
01371   mrgCtx.numValidMergeCand = uiArrayAddr;
01372 }
