01374 bool PU::checkDMVRCondition(const PredictionUnit& pu)
01375 {
01376   if (pu.cs->sps->getUseDMVR() && !pu.cs->picHeader->getDmvrDisabledFlag())
01377   {
01378     const int refIdx0 = pu.refIdx[REF_PIC_LIST_0];
01379     const int refIdx1 = pu.refIdx[REF_PIC_LIST_1];
01380 
01381     const WPScalingParam *wp0 = pu.cu->slice->getWpScaling(REF_PIC_LIST_0, refIdx0);
01382     const WPScalingParam *wp1 = pu.cu->slice->getWpScaling(REF_PIC_LIST_1, refIdx1);
01383 
01384     const bool ref0IsScaled = refIdx0 < 0 || refIdx0 >= MAX_NUM_REF
01385                                 ? false
01386                                 : pu.cu->slice->getRefPic(REF_PIC_LIST_0, refIdx0)->isRefScaled(pu.cs->pps);
01387     const bool ref1IsScaled = refIdx1 < 0 || refIdx1 >= MAX_NUM_REF
01388                                 ? false
01389                                 : pu.cu->slice->getRefPic(REF_PIC_LIST_1, refIdx1)->isRefScaled(pu.cs->pps);
01390 
01391     return pu.mergeFlag && pu.mergeType == MRG_TYPE_DEFAULT_N && !pu.ciipFlag && !pu.cu->affine && !pu.mmvdMergeFlag
01392            && !pu.cu->mmvdSkip && PU::isBiPredFromDifferentDirEqDistPoc(pu) && (pu.lheight() >= 8) && (pu.lwidth() >= 8)
01393            && ((pu.lheight() * pu.lwidth()) >= 128) && (pu.cu->BcwIdx == BCW_DEFAULT)
01394            && !WPScalingParam::isWeighted(wp0) && !WPScalingParam::isWeighted(wp1) && !ref0IsScaled && !ref1IsScaled;
01395   }
01396   else
01397   {
01398     return false;
01399   }
01400 }
