01402 
01403 static int xGetDistScaleFactor(const int &iCurrPOC, const int &iCurrRefPOC, const int &iColPOC, const int &iColRefPOC)
01404 {
01405   int iDiffPocD = iColPOC - iColRefPOC;
01406   int iDiffPocB = iCurrPOC - iCurrRefPOC;
01407 
01408   if (iDiffPocD == iDiffPocB)
01409   {
01410     return 4096;
01411   }
01412   else
01413   {
01414     int iTDB = Clip3(-128, 127, iDiffPocB);
01415     int iTDD = Clip3(-128, 127, iDiffPocD);
01416     int iX = (0x4000 + abs(iTDD / 2)) / iTDD;
01417     int iScale = Clip3(-4096, 4095, (iTDB * iX + 32) >> 6);
01418     return iScale;
01419   }
01420 }
01421 
01422 int convertMvFixedToFloat(int32_t val)
01423 {
01424   int sign  = val >> 31;
01425   int scale = floorLog2((val ^ sign) | MV_MANTISSA_UPPER_LIMIT) - (MV_MANTISSA_BITCOUNT - 1);
01426 
01427   int exponent;
01428   int mantissa;
01429   if (scale >= 0)
01430   {
01431     int round = (1 << scale) >> 1;
01432     int n     = (val + round) >> scale;
01433     exponent  = scale + ((n ^ sign) >> (MV_MANTISSA_BITCOUNT - 1));
01434     mantissa  = (n & MV_MANTISSA_UPPER_LIMIT) | (sign << (MV_MANTISSA_BITCOUNT - 1));
01435   }
01436   else
01437   {
01438     exponent = 0;
01439     mantissa = val;
01440   }
01441 
01442   return exponent | (mantissa << MV_EXPONENT_BITCOUNT);
01443 }
01444 
01445 int convertMvFloatToFixed(int val)
01446 {
01447   int exponent = val & MV_EXPONENT_MASK;
01448   int mantissa = val >> MV_EXPONENT_BITCOUNT;
01449   return exponent == 0 ? mantissa : (mantissa ^ MV_MANTISSA_LIMIT) << (exponent - 1);
01450 }
01451 
01452 int roundMvComp(int x)
01453 {
01454   return convertMvFloatToFixed(convertMvFixedToFloat(x));
01455 }
01456 
01457 int PU::getDistScaleFactor(const int &currPOC, const int &currRefPOC, const int &colPOC, const int &colRefPOC)
01458 {
01459   return xGetDistScaleFactor(currPOC, currRefPOC, colPOC, colRefPOC);
01460 }
01461 
01462 void PU::getInterMMVDMergeCandidates(const PredictionUnit &pu, MergeCtx& mrgCtx, const int& mrgCandIdx)
01463 {
01464   int refIdxList0, refIdxList1;
01465   int k;
01466   int currBaseNum = 0;
01467   const uint16_t maxNumMergeCand = mrgCtx.numValidMergeCand;
01468 
01469   for (k = 0; k < maxNumMergeCand; k++)
01470   {
01471     if (mrgCtx.mrgTypeNeighbours[k] == MRG_TYPE_DEFAULT_N)
01472     {
01473       refIdxList0 = mrgCtx.mvFieldNeighbours[(k << 1)].refIdx;
01474       refIdxList1 = mrgCtx.mvFieldNeighbours[(k << 1) + 1].refIdx;
01475 
01476       if ((refIdxList0 >= 0) && (refIdxList1 >= 0))
01477       {
01478         mrgCtx.mmvdBaseMv[currBaseNum][0] = mrgCtx.mvFieldNeighbours[(k << 1)];
01479         mrgCtx.mmvdBaseMv[currBaseNum][1] = mrgCtx.mvFieldNeighbours[(k << 1) + 1];
01480       }
01481       else if (refIdxList0 >= 0)
01482       {
01483         mrgCtx.mmvdBaseMv[currBaseNum][0] = mrgCtx.mvFieldNeighbours[(k << 1)];
01484         mrgCtx.mmvdBaseMv[currBaseNum][1] = MvField(Mv(0, 0), -1);
01485       }
01486       else if (refIdxList1 >= 0)
01487       {
01488         mrgCtx.mmvdBaseMv[currBaseNum][0] = MvField(Mv(0, 0), -1);
01489         mrgCtx.mmvdBaseMv[currBaseNum][1] = mrgCtx.mvFieldNeighbours[(k << 1) + 1];
01490       }
01491       mrgCtx.mmvdUseAltHpelIf[currBaseNum] = mrgCtx.useAltHpelIf[k];
01492 
01493       currBaseNum++;
01494 
01495       if (currBaseNum == MMVD_BASE_MV_NUM)
01496       {
01497         break;
01498       }
01499     }
01500   }
01501 }
01502 bool PU::getColocatedMVP(const PredictionUnit &pu, const RefPicList &eRefPicList, const Position &_pos, Mv& rcMv, const int &refIdx, bool sbFlag)
01503 {
01504   // don't perform MV compression when generally disabled or subPuMvp is used
01505   const unsigned scale = 4 * std::max<int>(1, 4 * AMVP_DECIMATION_FACTOR / 4);
01506   const unsigned mask  = ~( scale - 1 );
01507 
01508   const Position pos = Position{ PosType( _pos.x & mask ), PosType( _pos.y & mask ) };
01509 
01510   const Slice &slice = *pu.cs->slice;
01511 
01512   // use coldir.
01513   const Picture* const pColPic = slice.getRefPic(RefPicList(slice.isInterB() ? 1 - slice.getColFromL0Flag() : 0), slice.getColRefIdx());
01514 
01515   if( !pColPic )
01516   {
01517     return false;
01518   }
01519 
01520   // Check the position of colocated block is within a subpicture
01521   const SubPic &curSubPic = pu.cs->slice->getPPS()->getSubPicFromPos(pu.lumaPos());
01522   if (curSubPic.getTreatedAsPicFlag())
01523   {
01524     if (!curSubPic.isContainingPos(pos))
01525     {
01526       return false;
01527     }
01528   }
01529   RefPicList eColRefPicList = slice.getCheckLDC() ? eRefPicList : RefPicList(slice.getColFromL0Flag());
01530 
01531   const MotionInfo& mi = pColPic->cs->getMotionInfo( pos );
01532 
01533   if( !mi.isInter )
01534   {
01535     return false;
01536   }
01537   if (mi.isIBCmot)
01538   {
01539     return false;
01540   }
01541   if (CU::isIBC(*pu.cu))
01542   {
01543     return false;
01544   }
01545   int iColRefIdx = mi.refIdx[eColRefPicList];
01546 
01547   if (sbFlag && !slice.getCheckLDC())
01548   {
01549     eColRefPicList = eRefPicList;
01550     iColRefIdx = mi.refIdx[eColRefPicList];
01551     if (iColRefIdx < 0)
01552     {
01553       return false;
01554     }
01555   }
01556   else
01557   {
01558     if (iColRefIdx < 0)
01559     {
01560       eColRefPicList = RefPicList(1 - eColRefPicList);
01561       iColRefIdx = mi.refIdx[eColRefPicList];
01562 
01563       if (iColRefIdx < 0)
01564       {
01565         return false;
01566       }
01567     }
01568   }
01569 
01570   const Slice *pColSlice = nullptr;
01571 
01572   for( const auto s : pColPic->slices )
01573   {
01574     if( s->getIndependentSliceIdx() == mi.sliceIdx )
01575     {
01576       pColSlice = s;
01577       break;
01578     }
01579   }
01580 
01581   CHECK( pColSlice == nullptr, "Slice segment not found" );
01582 
01583   const Slice &colSlice = *pColSlice;
01584 
01585   const bool bIsCurrRefLongTerm = slice.getRefPic(eRefPicList, refIdx)->longTerm;
01586   const bool bIsColRefLongTerm  = colSlice.getIsUsedAsLongTerm(eColRefPicList, iColRefIdx);
01587 
01588   if (bIsCurrRefLongTerm != bIsColRefLongTerm)
01589   {
01590     return false;
01591   }
01592 
01593 
01594   // Scale the vector.
01595   Mv cColMv = mi.mv[eColRefPicList];
01596   cColMv.setHor(roundMvComp(cColMv.getHor()));
01597   cColMv.setVer(roundMvComp(cColMv.getVer()));
01598 
01599   if (bIsCurrRefLongTerm /*|| bIsColRefLongTerm*/)
01600   {
01601     rcMv = cColMv;
01602     rcMv.clipToStorageBitDepth();
01603   }
01604   else
01605   {
01606     const int currPOC    = slice.getPOC();
01607     const int colPOC     = colSlice.getPOC();
01608     const int colRefPOC  = colSlice.getRefPOC(eColRefPicList, iColRefIdx);
01609     const int currRefPOC = slice.getRefPic(eRefPicList, refIdx)->getPOC();
01610     const int distscale  = xGetDistScaleFactor(currPOC, currRefPOC, colPOC, colRefPOC);
01611 
01612     if (distscale == 4096)
01613     {
01614       rcMv = cColMv;
01615       rcMv.clipToStorageBitDepth();
01616     }
01617     else
01618     {
01619       rcMv = cColMv.scaleMv(distscale);
01620     }
01621   }
01622 
01623   return true;
01624 }
