01626 bool PU::isDiffMER(const Position &pos1, const Position &pos2, const unsigned plevel)
01627 {
01628   const unsigned xN = pos1.x;
01629   const unsigned yN = pos1.y;
01630   const unsigned xP = pos2.x;
01631   const unsigned yP = pos2.y;
01632 
01633   if ((xN >> plevel) != (xP >> plevel))
01634   {
01635     return true;
01636   }
01637 
01638   if ((yN >> plevel) != (yP >> plevel))
01639   {
01640     return true;
01641   }
01642 
01643   return false;
01644 }
