01646 bool PU::isAddNeighborMv(const Mv& currMv, Mv* neighborMvs, int numNeighborMv)
01647 {
01648   bool existed = false;
01649   for (uint32_t cand = 0; cand < numNeighborMv && !existed; cand++)
01650   {
01651     if (currMv == neighborMvs[cand])
01652     {
01653       existed = true;
01654     }
01655   }
01656 
01657   if (!existed)
01658   {
01659     return true;
01660   }
01661   else
01662   {
01663     return false;
01664   }
01665 }
01666 
01667 void PU::getIbcMVPsEncOnly(PredictionUnit &pu, Mv* mvPred, int& nbPred)
01668 {
01669   const PreCalcValues   &pcv = *pu.cs->pcv;
01670   const int  cuWidth = pu.blocks[COMPONENT_Y].width;
01671   const int  cuHeight = pu.blocks[COMPONENT_Y].height;
01672   const int  log2UnitWidth = floorLog2(pcv.minCUWidth);
01673   const int  log2UnitHeight = floorLog2(pcv.minCUHeight);
01674   const int  totalAboveUnits = (cuWidth >> log2UnitWidth) + 1;
01675   const int  totalLeftUnits = (cuHeight >> log2UnitHeight) + 1;
01676 
01677   nbPred = 0;
01678   Position posLT = pu.Y().topLeft();
01679 
01680   // above-left
01681   const PredictionUnit *aboveLeftPU = pu.cs->getPURestricted(posLT.offset(-1, -1), pu, CHANNEL_TYPE_LUMA);
01682   if (aboveLeftPU && CU::isIBC(*aboveLeftPU->cu))
01683   {
01684     if (isAddNeighborMv(aboveLeftPU->bv, mvPred, nbPred))
01685     {
01686       mvPred[nbPred++] = aboveLeftPU->bv;
01687     }
01688   }
01689 
01690   // above neighbors
01691   for (uint32_t dx = 0; dx < totalAboveUnits && nbPred < IBC_NUM_CANDIDATES; dx++)
01692   {
01693     const PredictionUnit* tmpPU = pu.cs->getPURestricted(posLT.offset((dx << log2UnitWidth), -1), pu, CHANNEL_TYPE_LUMA);
01694     if (tmpPU && CU::isIBC(*tmpPU->cu))
01695     {
01696       if (isAddNeighborMv(tmpPU->bv, mvPred, nbPred))
01697       {
01698         mvPred[nbPred++] = tmpPU->bv;
01699       }
01700     }
01701   }
01702 
01703   // left neighbors
01704   for (uint32_t dy = 0; dy < totalLeftUnits && nbPred < IBC_NUM_CANDIDATES; dy++)
01705   {
01706     const PredictionUnit* tmpPU = pu.cs->getPURestricted(posLT.offset(-1, (dy << log2UnitHeight)), pu, CHANNEL_TYPE_LUMA);
01707     if (tmpPU && CU::isIBC(*tmpPU->cu))
01708     {
01709       if (isAddNeighborMv(tmpPU->bv, mvPred, nbPred))
01710       {
01711         mvPred[nbPred++] = tmpPU->bv;
01712       }
01713     }
01714   }
01715 
01716   size_t numAvaiCandInLUT = pu.cs->motionLut.lutIbc.size();
01717   for (uint32_t cand = 0; cand < numAvaiCandInLUT && nbPred < IBC_NUM_CANDIDATES; cand++)
01718   {
01719     MotionInfo neibMi = pu.cs->motionLut.lutIbc[cand];
01720     if (isAddNeighborMv(neibMi.bv, mvPred, nbPred))
01721     {
01722       mvPred[nbPred++] = neibMi.bv;
01723     }
01724   }
01725 
01726   bool isBvCandDerived[IBC_NUM_CANDIDATES];
01727   ::memset(isBvCandDerived, false, IBC_NUM_CANDIDATES);
01728 
01729   int curNbPred = nbPred;
01730   if (curNbPred < IBC_NUM_CANDIDATES)
01731   {
01732     do
01733     {
01734       curNbPred = nbPred;
01735       for (uint32_t idx = 0; idx < curNbPred && nbPred < IBC_NUM_CANDIDATES; idx++)
01736       {
01737         if (!isBvCandDerived[idx])
01738         {
01739           Mv derivedBv;
01740           if (getDerivedBV(pu, mvPred[idx], derivedBv))
01741           {
01742             if (isAddNeighborMv(derivedBv, mvPred, nbPred))
01743             {
01744               mvPred[nbPred++] = derivedBv;
01745             }
01746           }
01747           isBvCandDerived[idx] = true;
01748         }
01749       }
01750     } while (nbPred > curNbPred && nbPred < IBC_NUM_CANDIDATES);
01751   }
01752 }
01753 
01754 bool PU::getDerivedBV(PredictionUnit &pu, const Mv& currentMv, Mv& derivedMv)
01755 {
01756   int   cuPelX = pu.lumaPos().x;
01757   int   cuPelY = pu.lumaPos().y;
01758   int rX = cuPelX + currentMv.getHor();
01759   int rY = cuPelY + currentMv.getVer();
01760   int offsetX = currentMv.getHor();
01761   int offsetY = currentMv.getVer();
01762 
01763   if( rX < 0 || rY < 0 || rX >= pu.cs->slice->getPPS()->getPicWidthInLumaSamples() || rY >= pu.cs->slice->getPPS()->getPicHeightInLumaSamples() )
01764   {
01765     return false;
01766   }
01767 
01768   const PredictionUnit *neibRefPU = NULL;
01769   neibRefPU = pu.cs->getPURestricted(pu.lumaPos().offset(offsetX, offsetY), pu, CHANNEL_TYPE_LUMA);
01770 
01771   bool isIBC = (neibRefPU) ? CU::isIBC(*neibRefPU->cu) : 0;
01772   if (isIBC)
01773   {
01774     derivedMv = neibRefPU->bv;
01775     derivedMv += currentMv;
01776   }
01777   return isIBC;
01778 }
