01783 void PU::fillIBCMvpCand(PredictionUnit &pu, AMVPInfo &amvpInfo)
01784 {
01785   AMVPInfo *pInfo = &amvpInfo;
01786 
01787   pInfo->numCand = 0;
01788 
01789   MergeCtx mergeCtx;
01790   PU::getIBCMergeCandidates(pu, mergeCtx, AMVP_MAX_NUM_CANDS - 1);
01791   int candIdx = 0;
01792   while (pInfo->numCand < AMVP_MAX_NUM_CANDS)
01793   {
01794     pInfo->mvCand[pInfo->numCand] = mergeCtx.mvFieldNeighbours[(candIdx << 1) + 0].mv;;
01795     pInfo->numCand++;
01796     candIdx++;
01797   }
01798 
01799   for (Mv &mv : pInfo->mvCand)
01800   {
01801     mv.roundIbcPrecInternal2Amvr(pu.cu->imv);
01802   }
01803 }
