01805 
01813 void PU::fillMvpCand(PredictionUnit &pu, const RefPicList &eRefPicList, const int &refIdx, AMVPInfo &amvpInfo)
01814 {
01815   CodingStructure &cs = *pu.cs;
01816 
01817   AMVPInfo *pInfo = &amvpInfo;
01818 
01819   pInfo->numCand = 0;
01820 
01821   if (refIdx < 0)
01822   {
01823     return;
01824   }
01825 
01826   //-- Get Spatial MV
01827   Position posLT = pu.Y().topLeft();
01828   Position posRT = pu.Y().topRight();
01829   Position posLB = pu.Y().bottomLeft();
01830 
01831   {
01832     bool bAdded = addMVPCandUnscaled( pu, eRefPicList, refIdx, posLB, MD_BELOW_LEFT, *pInfo );
01833 
01834     if( !bAdded )
01835     {
01836       bAdded = addMVPCandUnscaled( pu, eRefPicList, refIdx, posLB, MD_LEFT, *pInfo );
01837 
01838     }
01839   }
01840 
01841   // Above predictor search
01842   {
01843     bool bAdded = addMVPCandUnscaled( pu, eRefPicList, refIdx, posRT, MD_ABOVE_RIGHT, *pInfo );
01844 
01845     if( !bAdded )
01846     {
01847       bAdded = addMVPCandUnscaled( pu, eRefPicList, refIdx, posRT, MD_ABOVE, *pInfo );
01848 
01849       if( !bAdded )
01850       {
01851         addMVPCandUnscaled( pu, eRefPicList, refIdx, posLT, MD_ABOVE_LEFT, *pInfo );
01852       }
01853     }
01854   }
01855 
01856   for( int i = 0; i < pInfo->numCand; i++ )
01857   {
01858     pInfo->mvCand[i].roundTransPrecInternal2Amvr(pu.cu->imv);
01859   }
01860 
01861   if( pInfo->numCand == 2 )
01862   {
01863     if( pInfo->mvCand[0] == pInfo->mvCand[1] )
01864     {
01865       pInfo->numCand = 1;
01866     }
01867   }
01868 
01869   if (cs.picHeader->getEnableTMVPFlag() && pInfo->numCand < AMVP_MAX_NUM_CANDS && (pu.lumaSize().width + pu.lumaSize().height > 12))
01870   {
01871     // Get Temporal Motion Predictor
01872     const int refIdx_Col = refIdx;
01873 
01874     Position posRB = pu.Y().bottomRight().offset(-3, -3);
01875 
01876     const PreCalcValues& pcv = *cs.pcv;
01877 
01878     Position posC0;
01879     bool C0Avail = false;
01880     Position posC1 = pu.Y().center();
01881     Mv cColMv;
01882 
01883     bool boundaryCond = ((posRB.x + pcv.minCUWidth) < pcv.lumaWidth) && ((posRB.y + pcv.minCUHeight) < pcv.lumaHeight);
01884     const SubPic &curSubPic = pu.cs->slice->getPPS()->getSubPicFromPos(pu.lumaPos());
01885     if (curSubPic.getTreatedAsPicFlag())
01886     {
01887       boundaryCond = ((posRB.x + pcv.minCUWidth) <= curSubPic.getSubPicRight() &&
01888                       (posRB.y + pcv.minCUHeight) <= curSubPic.getSubPicBottom());
01889     }
01890     if (boundaryCond)
01891     {
01892       int posYInCtu = posRB.y & pcv.maxCUHeightMask;
01893       if (posYInCtu + 4 < pcv.maxCUHeight)
01894       {
01895         posC0 = posRB.offset(4, 4);
01896         C0Avail = true;
01897       }
01898     }
01899     if ( ( C0Avail && getColocatedMVP( pu, eRefPicList, posC0, cColMv, refIdx_Col, false ) ) || getColocatedMVP( pu, eRefPicList, posC1, cColMv, refIdx_Col, false ) )
01900     {
01901       cColMv.roundTransPrecInternal2Amvr(pu.cu->imv);
01902       pInfo->mvCand[pInfo->numCand++] = cColMv;
01903     }
01904   }
01905 
01906   if (pInfo->numCand < AMVP_MAX_NUM_CANDS)
01907   {
01908     const int currRefPOC = cs.slice->getRefPic(eRefPicList, refIdx)->getPOC();
01909     addAMVPHMVPCand(pu, eRefPicList, currRefPOC, *pInfo);
01910   }
01911 
01912   if (pInfo->numCand > AMVP_MAX_NUM_CANDS)
01913   {
01914     pInfo->numCand = AMVP_MAX_NUM_CANDS;
01915   }
01916 
01917   while (pInfo->numCand < AMVP_MAX_NUM_CANDS)
01918   {
01919     pInfo->mvCand[pInfo->numCand] = Mv( 0, 0 );
01920     pInfo->numCand++;
01921   }
01922 
01923   for (Mv &mv : pInfo->mvCand)
01924   {
01925     mv.roundTransPrecInternal2Amvr(pu.cu->imv);
01926   }
01927 }
01928 
01929 bool PU::addAffineMVPCandUnscaled( const PredictionUnit &pu, const RefPicList &refPicList, const int &refIdx, const Position &pos, const MvpDir &dir, AffineAMVPInfo &affiAMVPInfo )
01930 {
01931   CodingStructure &cs = *pu.cs;
01932   const PredictionUnit *neibPU = NULL;
01933   Position neibPos;
01934 
01935   switch ( dir )
01936   {
01937   case MD_LEFT:
01938     neibPos = pos.offset( -1, 0 );
01939     break;
01940   case MD_ABOVE:
01941     neibPos = pos.offset( 0, -1 );
01942     break;
01943   case MD_ABOVE_RIGHT:
01944     neibPos = pos.offset( 1, -1 );
01945     break;
01946   case MD_BELOW_LEFT:
01947     neibPos = pos.offset( -1, 1 );
01948     break;
01949   case MD_ABOVE_LEFT:
01950     neibPos = pos.offset( -1, -1 );
01951     break;
01952   default:
01953     break;
01954   }
01955 
01956   neibPU = cs.getPURestricted( neibPos, pu, pu.chType );
01957 
01958   if (neibPU == NULL || !CU::isInter(*neibPU->cu) || !neibPU->cu->affine || neibPU->mergeType != MRG_TYPE_DEFAULT_N)
01959   {
01960     return false;
01961   }
01962 
01963   Mv outputAffineMv[3];
01964   const MotionInfo& neibMi = neibPU->getMotionInfo( neibPos );
01965 
01966   const int        currRefPOC = cs.slice->getRefPic( refPicList, refIdx )->getPOC();
01967   const RefPicList refPicList2nd = (refPicList == REF_PIC_LIST_0) ? REF_PIC_LIST_1 : REF_PIC_LIST_0;
01968 
01969   for ( int predictorSource = 0; predictorSource < 2; predictorSource++ ) // examine the indicated reference picture list, then if not available, examine the other list.
01970   {
01971     const RefPicList eRefPicListIndex = (predictorSource == 0) ? refPicList : refPicList2nd;
01972     const int        neibRefIdx = neibMi.refIdx[eRefPicListIndex];
01973 
01974     if ( ((neibPU->interDir & (eRefPicListIndex + 1)) == 0) || pu.cu->slice->getRefPOC( eRefPicListIndex, neibRefIdx ) != currRefPOC )
01975     {
01976       continue;
01977     }
01978 
01979     xInheritedAffineMv( pu, neibPU, eRefPicListIndex, outputAffineMv );
01980     outputAffineMv[0].roundAffinePrecInternal2Amvr(pu.cu->imv);
01981     outputAffineMv[1].roundAffinePrecInternal2Amvr(pu.cu->imv);
01982     affiAMVPInfo.mvCandLT[affiAMVPInfo.numCand] = outputAffineMv[0];
01983     affiAMVPInfo.mvCandRT[affiAMVPInfo.numCand] = outputAffineMv[1];
01984     if ( pu.cu->affineType == AFFINEMODEL_6PARAM )
01985     {
01986       outputAffineMv[2].roundAffinePrecInternal2Amvr(pu.cu->imv);
01987       affiAMVPInfo.mvCandLB[affiAMVPInfo.numCand] = outputAffineMv[2];
01988     }
01989     affiAMVPInfo.numCand++;
01990     return true;
01991   }
01992 
01993   return false;
01994 }
01995 
01996 void PU::xInheritedAffineMv( const PredictionUnit &pu, const PredictionUnit* puNeighbour, RefPicList eRefPicList, Mv rcMv[3] )
01997 {
01998   int posNeiX = puNeighbour->Y().pos().x;
01999   int posNeiY = puNeighbour->Y().pos().y;
02000   int posCurX = pu.Y().pos().x;
02001   int posCurY = pu.Y().pos().y;
02002 
02003   int neiW = puNeighbour->Y().width;
02004   int curW = pu.Y().width;
02005   int neiH = puNeighbour->Y().height;
02006   int curH = pu.Y().height;
02007 
02008   Mv mvLT, mvRT, mvLB;
02009   mvLT = puNeighbour->mvAffi[eRefPicList][0];
02010   mvRT = puNeighbour->mvAffi[eRefPicList][1];
02011   mvLB = puNeighbour->mvAffi[eRefPicList][2];
02012 
02013   bool isTopCtuBoundary = false;
02014   if ( (posNeiY + neiH) % pu.cs->sps->getCTUSize() == 0 && (posNeiY + neiH) == posCurY )
02015   {
02016     // use bottom-left and bottom-right sub-block MVs for inheritance
02017     const Position posRB = puNeighbour->Y().bottomRight();
02018     const Position posLB = puNeighbour->Y().bottomLeft();
02019     mvLT = puNeighbour->getMotionInfo( posLB ).mv[eRefPicList];
02020     mvRT = puNeighbour->getMotionInfo( posRB ).mv[eRefPicList];
02021     posNeiY += neiH;
02022     isTopCtuBoundary = true;
02023   }
02024 
02025   int shift = MAX_CU_DEPTH;
02026   int iDMvHorX, iDMvHorY, iDMvVerX, iDMvVerY;
02027 
02028   iDMvHorX = (mvRT - mvLT).getHor() << (shift - floorLog2(neiW));
02029   iDMvHorY = (mvRT - mvLT).getVer() << (shift - floorLog2(neiW));
02030   if ( puNeighbour->cu->affineType == AFFINEMODEL_6PARAM && !isTopCtuBoundary )
02031   {
02032     iDMvVerX = (mvLB - mvLT).getHor() << (shift - floorLog2(neiH));
02033     iDMvVerY = (mvLB - mvLT).getVer() << (shift - floorLog2(neiH));
02034   }
02035   else
02036   {
02037     iDMvVerX = -iDMvHorY;
02038     iDMvVerY = iDMvHorX;
02039   }
02040 
02041   int iMvScaleHor = mvLT.getHor() << shift;
02042   int iMvScaleVer = mvLT.getVer() << shift;
02043   int horTmp, verTmp;
02044 
02045   // v0
02046   horTmp = iMvScaleHor + iDMvHorX * (posCurX - posNeiX) + iDMvVerX * (posCurY - posNeiY);
02047   verTmp = iMvScaleVer + iDMvHorY * (posCurX - posNeiX) + iDMvVerY * (posCurY - posNeiY);
02048   roundAffineMv( horTmp, verTmp, shift );
02049   rcMv[0].hor = horTmp;
02050   rcMv[0].ver = verTmp;
02051   rcMv[0].clipToStorageBitDepth();
02052 
02053   // v1
02054   horTmp = iMvScaleHor + iDMvHorX * (posCurX + curW - posNeiX) + iDMvVerX * (posCurY - posNeiY);
02055   verTmp = iMvScaleVer + iDMvHorY * (posCurX + curW - posNeiX) + iDMvVerY * (posCurY - posNeiY);
02056   roundAffineMv( horTmp, verTmp, shift );
02057   rcMv[1].hor = horTmp;
02058   rcMv[1].ver = verTmp;
02059   rcMv[1].clipToStorageBitDepth();
02060 
02061   // v2
02062   if ( pu.cu->affineType == AFFINEMODEL_6PARAM )
02063   {
02064     horTmp = iMvScaleHor + iDMvHorX * (posCurX - posNeiX) + iDMvVerX * (posCurY + curH - posNeiY);
02065     verTmp = iMvScaleVer + iDMvHorY * (posCurX - posNeiX) + iDMvVerY * (posCurY + curH - posNeiY);
02066     roundAffineMv( horTmp, verTmp, shift );
02067     rcMv[2].hor = horTmp;
02068     rcMv[2].ver = verTmp;
02069     rcMv[2].clipToStorageBitDepth();
02070   }
02071 }
02072 
02073 
02074 void PU::fillAffineMvpCand(PredictionUnit &pu, const RefPicList &eRefPicList, const int &refIdx, AffineAMVPInfo &affiAMVPInfo)
02075 {
02076   affiAMVPInfo.numCand = 0;
02077 
02078   if (refIdx < 0)
02079   {
02080     return;
02081   }
02082 
02083   // insert inherited affine candidates
02084   Mv outputAffineMv[3];
02085   Position posLT = pu.Y().topLeft();
02086   Position posRT = pu.Y().topRight();
02087   Position posLB = pu.Y().bottomLeft();
02088 
02089   // check left neighbor
02090   if ( !addAffineMVPCandUnscaled( pu, eRefPicList, refIdx, posLB, MD_BELOW_LEFT, affiAMVPInfo ) )
02091   {
02092     addAffineMVPCandUnscaled( pu, eRefPicList, refIdx, posLB, MD_LEFT, affiAMVPInfo );
02093   }
02094 
02095   // check above neighbor
02096   if ( !addAffineMVPCandUnscaled( pu, eRefPicList, refIdx, posRT, MD_ABOVE_RIGHT, affiAMVPInfo ) )
02097   {
02098     if ( !addAffineMVPCandUnscaled( pu, eRefPicList, refIdx, posRT, MD_ABOVE, affiAMVPInfo ) )
02099     {
02100       addAffineMVPCandUnscaled( pu, eRefPicList, refIdx, posLT, MD_ABOVE_LEFT, affiAMVPInfo );
02101     }
02102   }
02103 
02104   if ( affiAMVPInfo.numCand >= AMVP_MAX_NUM_CANDS )
02105   {
02106     for (int i = 0; i < affiAMVPInfo.numCand; i++)
02107     {
02108       affiAMVPInfo.mvCandLT[i].roundAffinePrecInternal2Amvr(pu.cu->imv);
02109       affiAMVPInfo.mvCandRT[i].roundAffinePrecInternal2Amvr(pu.cu->imv);
02110       affiAMVPInfo.mvCandLB[i].roundAffinePrecInternal2Amvr(pu.cu->imv);
02111     }
02112     return;
02113   }
02114 
02115   // insert constructed affine candidates
02116   int cornerMVPattern = 0;
02117 
02118   //-------------------  V0 (START) -------------------//
02119   AMVPInfo amvpInfo0;
02120   amvpInfo0.numCand = 0;
02121 
02122   // A->C: Above Left, Above, Left
02123   addMVPCandUnscaled( pu, eRefPicList, refIdx, posLT, MD_ABOVE_LEFT, amvpInfo0 );
02124   if ( amvpInfo0.numCand < 1 )
02125   {
02126     addMVPCandUnscaled( pu, eRefPicList, refIdx, posLT, MD_ABOVE, amvpInfo0 );
02127   }
02128   if ( amvpInfo0.numCand < 1 )
02129   {
02130     addMVPCandUnscaled( pu, eRefPicList, refIdx, posLT, MD_LEFT, amvpInfo0 );
02131   }
02132   cornerMVPattern = cornerMVPattern | amvpInfo0.numCand;
02133 
02134   //-------------------  V1 (START) -------------------//
02135   AMVPInfo amvpInfo1;
02136   amvpInfo1.numCand = 0;
02137 
02138   // D->E: Above, Above Right
02139   addMVPCandUnscaled( pu, eRefPicList, refIdx, posRT, MD_ABOVE, amvpInfo1 );
02140   if ( amvpInfo1.numCand < 1 )
02141   {
02142     addMVPCandUnscaled( pu, eRefPicList, refIdx, posRT, MD_ABOVE_RIGHT, amvpInfo1 );
02143   }
02144   cornerMVPattern = cornerMVPattern | (amvpInfo1.numCand << 1);
02145 
02146   //-------------------  V2 (START) -------------------//
02147   AMVPInfo amvpInfo2;
02148   amvpInfo2.numCand = 0;
02149 
02150   // F->G: Left, Below Left
02151   addMVPCandUnscaled( pu, eRefPicList, refIdx, posLB, MD_LEFT, amvpInfo2 );
02152   if ( amvpInfo2.numCand < 1 )
02153   {
02154     addMVPCandUnscaled( pu, eRefPicList, refIdx, posLB, MD_BELOW_LEFT, amvpInfo2 );
02155   }
02156   cornerMVPattern = cornerMVPattern | (amvpInfo2.numCand << 2);
02157 
02158   outputAffineMv[0] = amvpInfo0.mvCand[0];
02159   outputAffineMv[1] = amvpInfo1.mvCand[0];
02160   outputAffineMv[2] = amvpInfo2.mvCand[0];
02161 
02162   outputAffineMv[0].roundAffinePrecInternal2Amvr(pu.cu->imv);
02163   outputAffineMv[1].roundAffinePrecInternal2Amvr(pu.cu->imv);
02164   outputAffineMv[2].roundAffinePrecInternal2Amvr(pu.cu->imv);
02165 
02166   if ( cornerMVPattern == 7 || (cornerMVPattern == 3 && pu.cu->affineType == AFFINEMODEL_4PARAM) )
02167   {
02168     affiAMVPInfo.mvCandLT[affiAMVPInfo.numCand] = outputAffineMv[0];
02169     affiAMVPInfo.mvCandRT[affiAMVPInfo.numCand] = outputAffineMv[1];
02170     affiAMVPInfo.mvCandLB[affiAMVPInfo.numCand] = outputAffineMv[2];
02171     affiAMVPInfo.numCand++;
02172   }
02173 
02174   if ( affiAMVPInfo.numCand < 2 )
02175   {
02176     // check corner MVs
02177     for ( int i = 2; i >= 0 && affiAMVPInfo.numCand < AMVP_MAX_NUM_CANDS; i-- )
02178     {
02179       if ( cornerMVPattern & (1 << i) ) // MV i exist
02180       {
02181         affiAMVPInfo.mvCandLT[affiAMVPInfo.numCand] = outputAffineMv[i];
02182         affiAMVPInfo.mvCandRT[affiAMVPInfo.numCand] = outputAffineMv[i];
02183         affiAMVPInfo.mvCandLB[affiAMVPInfo.numCand] = outputAffineMv[i];
02184         affiAMVPInfo.numCand++;
02185       }
02186     }
02187 
02188     // Get Temporal Motion Predictor
02189     if ( affiAMVPInfo.numCand < 2 && pu.cs->picHeader->getEnableTMVPFlag() )
02190     {
02191       const int refIdxCol = refIdx;
02192 
02193       Position posRB = pu.Y().bottomRight().offset( -3, -3 );
02194 
02195       const PreCalcValues& pcv = *pu.cs->pcv;
02196 
02197       Position posC0;
02198       bool C0Avail = false;
02199       Position posC1 = pu.Y().center();
02200       Mv cColMv;
02201       bool boundaryCond = ((posRB.x + pcv.minCUWidth) < pcv.lumaWidth) && ((posRB.y + pcv.minCUHeight) < pcv.lumaHeight);
02202       const SubPic &curSubPic = pu.cs->slice->getPPS()->getSubPicFromPos(pu.lumaPos());
02203       if (curSubPic.getTreatedAsPicFlag())
02204       {
02205         boundaryCond = ((posRB.x + pcv.minCUWidth) <= curSubPic.getSubPicRight() &&
02206           (posRB.y + pcv.minCUHeight) <= curSubPic.getSubPicBottom());
02207       }
02208       if (boundaryCond)
02209       {
02210         int posYInCtu = posRB.y & pcv.maxCUHeightMask;
02211         if (posYInCtu + 4 < pcv.maxCUHeight)
02212         {
02213           posC0 = posRB.offset(4, 4);
02214           C0Avail = true;
02215         }
02216       }
02217       if ( ( C0Avail && getColocatedMVP( pu, eRefPicList, posC0, cColMv, refIdxCol, false ) ) || getColocatedMVP( pu, eRefPicList, posC1, cColMv, refIdxCol, false ) )
02218       {
02219         cColMv.roundAffinePrecInternal2Amvr(pu.cu->imv);
02220         affiAMVPInfo.mvCandLT[affiAMVPInfo.numCand] = cColMv;
02221         affiAMVPInfo.mvCandRT[affiAMVPInfo.numCand] = cColMv;
02222         affiAMVPInfo.mvCandLB[affiAMVPInfo.numCand] = cColMv;
02223         affiAMVPInfo.numCand++;
02224       }
02225     }
02226 
02227     if ( affiAMVPInfo.numCand < 2 )
02228     {
02229       // add zero MV
02230       for ( int i = affiAMVPInfo.numCand; i < AMVP_MAX_NUM_CANDS; i++ )
02231       {
02232         affiAMVPInfo.mvCandLT[affiAMVPInfo.numCand].setZero();
02233         affiAMVPInfo.mvCandRT[affiAMVPInfo.numCand].setZero();
02234         affiAMVPInfo.mvCandLB[affiAMVPInfo.numCand].setZero();
02235         affiAMVPInfo.numCand++;
02236       }
02237     }
02238   }
02239 
02240   for (int i = 0; i < affiAMVPInfo.numCand; i++)
02241   {
02242     affiAMVPInfo.mvCandLT[i].roundAffinePrecInternal2Amvr(pu.cu->imv);
02243     affiAMVPInfo.mvCandRT[i].roundAffinePrecInternal2Amvr(pu.cu->imv);
02244     affiAMVPInfo.mvCandLB[i].roundAffinePrecInternal2Amvr(pu.cu->imv);
02245   }
02246 }
02247 
02248 bool PU::addMVPCandUnscaled( const PredictionUnit &pu, const RefPicList &eRefPicList, const int &iRefIdx, const Position &pos, const MvpDir &eDir, AMVPInfo &info )
02249 {
02250         CodingStructure &cs    = *pu.cs;
02251   const PredictionUnit *neibPU = NULL;
02252         Position neibPos;
02253 
02254   switch (eDir)
02255   {
02256   case MD_LEFT:
02257     neibPos = pos.offset( -1,  0 );
02258     break;
02259   case MD_ABOVE:
02260     neibPos = pos.offset(  0, -1 );
02261     break;
02262   case MD_ABOVE_RIGHT:
02263     neibPos = pos.offset(  1, -1 );
02264     break;
02265   case MD_BELOW_LEFT:
02266     neibPos = pos.offset( -1,  1 );
02267     break;
02268   case MD_ABOVE_LEFT:
02269     neibPos = pos.offset( -1, -1 );
02270     break;
02271   default:
02272     break;
02273   }
02274 
02275   neibPU = cs.getPURestricted( neibPos, pu, pu.chType );
02276 
02277   if( neibPU == NULL || !CU::isInter( *neibPU->cu ) )
02278   {
02279     return false;
02280   }
02281 
02282   const MotionInfo& neibMi        = neibPU->getMotionInfo( neibPos );
02283 
02284   const int        currRefPOC     = cs.slice->getRefPic( eRefPicList, iRefIdx )->getPOC();
02285   const RefPicList eRefPicList2nd = ( eRefPicList == REF_PIC_LIST_0 ) ? REF_PIC_LIST_1 : REF_PIC_LIST_0;
02286 
02287   for( int predictorSource = 0; predictorSource < 2; predictorSource++ ) // examine the indicated reference picture list, then if not available, examine the other list.
02288   {
02289     const RefPicList eRefPicListIndex = ( predictorSource == 0 ) ? eRefPicList : eRefPicList2nd;
02290     const int        neibRefIdx       = neibMi.refIdx[eRefPicListIndex];
02291 
02292     if( neibRefIdx >= 0 && currRefPOC == cs.slice->getRefPOC( eRefPicListIndex, neibRefIdx ) )
02293     {
02294       info.mvCand[info.numCand++] = neibMi.mv[eRefPicListIndex];
02295       return true;
02296     }
02297   }
02298 
02299   return false;
02300 }
