02302 
02303 void PU::addAMVPHMVPCand(const PredictionUnit &pu, const RefPicList eRefPicList, const int currRefPOC, AMVPInfo &info)
02304 {
02305   const Slice &slice = *(*pu.cs).slice;
02306 
02307   MotionInfo neibMi;
02308   auto &lut = CU::isIBC(*pu.cu) ? pu.cs->motionLut.lutIbc : pu.cs->motionLut.lut;
02309   int num_avai_candInLUT = (int) lut.size();
02310   int num_allowedCand = std::min(MAX_NUM_HMVP_AVMPCANDS, num_avai_candInLUT);
02311   const RefPicList eRefPicList2nd = (eRefPicList == REF_PIC_LIST_0) ? REF_PIC_LIST_1 : REF_PIC_LIST_0;
02312 
02313   for (int mrgIdx = 1; mrgIdx <= num_allowedCand; mrgIdx++)
02314   {
02315     if (info.numCand >= AMVP_MAX_NUM_CANDS)
02316     {
02317       return;
02318     }
02319     neibMi = lut[mrgIdx - 1];
02320 
02321     for (int predictorSource = 0; predictorSource < 2; predictorSource++)
02322     {
02323       const RefPicList eRefPicListIndex = (predictorSource == 0) ? eRefPicList : eRefPicList2nd;
02324       const int        neibRefIdx = neibMi.refIdx[eRefPicListIndex];
02325 
02326       if (neibRefIdx >= 0 && (CU::isIBC(*pu.cu) || (currRefPOC == slice.getRefPOC(eRefPicListIndex, neibRefIdx))))
02327       {
02328         Mv pmv = neibMi.mv[eRefPicListIndex];
02329         pmv.roundTransPrecInternal2Amvr(pu.cu->imv);
02330 
02331         info.mvCand[info.numCand++] = pmv;
02332         if (info.numCand >= AMVP_MAX_NUM_CANDS)
02333         {
02334           return;
02335         }
02336       }
02337     }
02338   }
02339 }
