02341 bool PU::isBipredRestriction(const PredictionUnit &pu)
02342 {
02343   if(pu.cu->lumaSize().width == 4 && pu.cu->lumaSize().height ==4 )
02344   {
02345     return true;
02346   }
02347   /* disable bi-prediction for 4x8/8x4 */
02348   if ( pu.cu->lumaSize().width + pu.cu->lumaSize().height == 12 )
02349   {
02350     return true;
02351   }
02352   return false;
02353 }
02354 
02355 void PU::getAffineControlPointCand(const PredictionUnit &pu, MotionInfo mi[4], bool isAvailable[4], int verIdx[4], int8_t bcwIdx, int modelIdx, int verNum, AffineMergeCtx& affMrgType)
02356 {
02357   int cuW = pu.Y().width;
02358   int cuH = pu.Y().height;
02359   int vx, vy;
02360   int shift = MAX_CU_DEPTH;
02361   int shiftHtoW = shift + floorLog2(cuW) - floorLog2(cuH);
02362 
02363   // motion info
02364   Mv cMv[2][4];
02365   int refIdx[2] = { -1, -1 };
02366   int dir = 0;
02367   EAffineModel curType = (verNum == 2) ? AFFINEMODEL_4PARAM : AFFINEMODEL_6PARAM;
02368 
02369   if ( verNum == 2 )
02370   {
02371     int idx0 = verIdx[0], idx1 = verIdx[1];
02372     if ( !isAvailable[idx0] || !isAvailable[idx1] )
02373     {
02374       return;
02375     }
02376 
02377     for ( int l = 0; l < 2; l++ )
02378     {
02379       if ( mi[idx0].refIdx[l] >= 0 && mi[idx1].refIdx[l] >= 0 )
02380       {
02381         // check same refidx and different mv
02382         if ( mi[idx0].refIdx[l] == mi[idx1].refIdx[l])
02383         {
02384           dir |= (l + 1);
02385           refIdx[l] = mi[idx0].refIdx[l];
02386         }
02387       }
02388     }
02389 
02390   }
02391   else if ( verNum == 3 )
02392   {
02393     int idx0 = verIdx[0], idx1 = verIdx[1], idx2 = verIdx[2];
02394     if ( !isAvailable[idx0] || !isAvailable[idx1] || !isAvailable[idx2] )
02395     {
02396       return;
02397     }
02398 
02399     for ( int l = 0; l < 2; l++ )
02400     {
02401       if ( mi[idx0].refIdx[l] >= 0 && mi[idx1].refIdx[l] >= 0 && mi[idx2].refIdx[l] >= 0 )
02402       {
02403         // check same refidx and different mv
02404         if ( mi[idx0].refIdx[l] == mi[idx1].refIdx[l] && mi[idx0].refIdx[l] == mi[idx2].refIdx[l])
02405         {
02406           dir |= (l + 1);
02407           refIdx[l] = mi[idx0].refIdx[l];
02408         }
02409       }
02410     }
02411 
02412   }
02413 
02414   if ( dir == 0 )
02415   {
02416     return;
02417   }
02418 
02419   for ( int l = 0; l < 2; l++ )
02420   {
02421     if ( dir & (l + 1) )
02422     {
02423       for ( int i = 0; i < verNum; i++ )
02424       {
02425         cMv[l][verIdx[i]] = mi[verIdx[i]].mv[l];
02426       }
02427 
02428       // convert to LT, RT[, [LB]]
02429       switch ( modelIdx )
02430       {
02431       case 0: // 0 : LT, RT, LB
02432         break;
02433 
02434       case 1: // 1 : LT, RT, RB
02435         cMv[l][2].hor = cMv[l][3].hor + cMv[l][0].hor - cMv[l][1].hor;
02436         cMv[l][2].ver = cMv[l][3].ver + cMv[l][0].ver - cMv[l][1].ver;
02437         cMv[l][2].clipToStorageBitDepth();
02438         break;
02439 
02440       case 2: // 2 : LT, LB, RB
02441         cMv[l][1].hor = cMv[l][3].hor + cMv[l][0].hor - cMv[l][2].hor;
02442         cMv[l][1].ver = cMv[l][3].ver + cMv[l][0].ver - cMv[l][2].ver;
02443         cMv[l][1].clipToStorageBitDepth();
02444         break;
02445 
02446       case 3: // 3 : RT, LB, RB
02447         cMv[l][0].hor = cMv[l][1].hor + cMv[l][2].hor - cMv[l][3].hor;
02448         cMv[l][0].ver = cMv[l][1].ver + cMv[l][2].ver - cMv[l][3].ver;
02449         cMv[l][0].clipToStorageBitDepth();
02450         break;
02451 
02452       case 4: // 4 : LT, RT
02453         break;
02454 
02455       case 5: // 5 : LT, LB
02456         vx = (cMv[l][0].hor << shift) + ((cMv[l][2].ver - cMv[l][0].ver) << shiftHtoW);
02457         vy = (cMv[l][0].ver << shift) - ((cMv[l][2].hor - cMv[l][0].hor) << shiftHtoW);
02458         roundAffineMv( vx, vy, shift );
02459         cMv[l][1].set( vx, vy );
02460         cMv[l][1].clipToStorageBitDepth();
02461         break;
02462 
02463       default:
02464         CHECK( 1, "Invalid model index!\n" );
02465         break;
02466       }
02467     }
02468     else
02469     {
02470       for ( int i = 0; i < 4; i++ )
02471       {
02472         cMv[l][i].hor = 0;
02473         cMv[l][i].ver = 0;
02474       }
02475     }
02476   }
02477 
02478   for ( int i = 0; i < 3; i++ )
02479   {
02480     affMrgType.mvFieldNeighbours[(affMrgType.numValidMergeCand << 1) + 0][i].mv = cMv[0][i];
02481     affMrgType.mvFieldNeighbours[(affMrgType.numValidMergeCand << 1) + 0][i].refIdx = refIdx[0];
02482 
02483     affMrgType.mvFieldNeighbours[(affMrgType.numValidMergeCand << 1) + 1][i].mv = cMv[1][i];
02484     affMrgType.mvFieldNeighbours[(affMrgType.numValidMergeCand << 1) + 1][i].refIdx = refIdx[1];
02485   }
02486   affMrgType.interDirNeighbours[affMrgType.numValidMergeCand] = dir;
02487   affMrgType.affineType[affMrgType.numValidMergeCand] = curType;
02488   affMrgType.BcwIdx[affMrgType.numValidMergeCand] = (dir == 3) ? bcwIdx : BCW_DEFAULT;
02489   affMrgType.numValidMergeCand++;
02490 
02491   return;
02492 }
02493 
02494 const int getAvailableAffineNeighboursForLeftPredictor( const PredictionUnit &pu, const PredictionUnit* npu[] )
02495 {
02496   const Position posLB = pu.Y().bottomLeft();
02497   int num = 0;
02498   const unsigned plevel = pu.cs->sps->getLog2ParallelMergeLevelMinus2() + 2;
02499 
02500   const PredictionUnit *puLeftBottom = pu.cs->getPURestricted( posLB.offset( -1, 1 ), pu, pu.chType );
02501   if (puLeftBottom && puLeftBottom->cu->affine && puLeftBottom->mergeType == MRG_TYPE_DEFAULT_N
02502       && PU::isDiffMER(pu.lumaPos(), posLB.offset(-1, 1), plevel))
02503   {
02504     npu[num++] = puLeftBottom;
02505     return num;
02506   }
02507 
02508   const PredictionUnit* puLeft = pu.cs->getPURestricted( posLB.offset( -1, 0 ), pu, pu.chType );
02509   if (puLeft && puLeft->cu->affine && puLeft->mergeType == MRG_TYPE_DEFAULT_N
02510       && PU::isDiffMER(pu.lumaPos(), posLB.offset(-1, 0), plevel))
02511   {
02512     npu[num++] = puLeft;
02513     return num;
02514   }
02515 
02516   return num;
02517 }
02518 
02519 const int getAvailableAffineNeighboursForAbovePredictor( const PredictionUnit &pu, const PredictionUnit* npu[], int numAffNeighLeft )
02520 {
02521   const Position posLT = pu.Y().topLeft();
02522   const Position posRT = pu.Y().topRight();
02523   const unsigned plevel = pu.cs->sps->getLog2ParallelMergeLevelMinus2() + 2;
02524   int num = numAffNeighLeft;
02525 
02526   const PredictionUnit* puAboveRight = pu.cs->getPURestricted( posRT.offset( 1, -1 ), pu, pu.chType );
02527   if (puAboveRight && puAboveRight->cu->affine && puAboveRight->mergeType == MRG_TYPE_DEFAULT_N
02528       && PU::isDiffMER(pu.lumaPos(), posRT.offset(1, -1), plevel))
02529   {
02530     npu[num++] = puAboveRight;
02531     return num;
02532   }
02533 
02534   const PredictionUnit* puAbove = pu.cs->getPURestricted( posRT.offset( 0, -1 ), pu, pu.chType );
02535   if (puAbove && puAbove->cu->affine && puAbove->mergeType == MRG_TYPE_DEFAULT_N
02536       && PU::isDiffMER(pu.lumaPos(), posRT.offset(0, -1), plevel))
02537   {
02538     npu[num++] = puAbove;
02539     return num;
02540   }
02541 
02542   const PredictionUnit *puAboveLeft = pu.cs->getPURestricted( posLT.offset( -1, -1 ), pu, pu.chType );
02543   if (puAboveLeft && puAboveLeft->cu->affine && puAboveLeft->mergeType == MRG_TYPE_DEFAULT_N
02544       && PU::isDiffMER(pu.lumaPos(), posLT.offset(-1, -1), plevel))
02545   {
02546     npu[num++] = puAboveLeft;
02547     return num;
02548   }
02549 
02550   return num;
02551 }
02552 
02553 void PU::getAffineMergeCand( const PredictionUnit &pu, AffineMergeCtx& affMrgCtx, const int mrgCandIdx )
02554 {
02555   const CodingStructure &cs = *pu.cs;
02556   const Slice &slice = *pu.cs->slice;
02557   const uint32_t maxNumAffineMergeCand = slice.getPicHeader()->getMaxNumAffineMergeCand();
02558   const unsigned plevel = pu.cs->sps->getLog2ParallelMergeLevelMinus2() + 2;
02559 
02560   for ( int i = 0; i < maxNumAffineMergeCand; i++ )
02561   {
02562     for ( int mvNum = 0; mvNum < 3; mvNum++ )
02563     {
02564       affMrgCtx.mvFieldNeighbours[(i << 1) + 0][mvNum].setMvField( Mv(), -1 );
02565       affMrgCtx.mvFieldNeighbours[(i << 1) + 1][mvNum].setMvField( Mv(), -1 );
02566     }
02567     affMrgCtx.interDirNeighbours[i] = 0;
02568     affMrgCtx.affineType[i] = AFFINEMODEL_4PARAM;
02569     affMrgCtx.mergeType[i] = MRG_TYPE_DEFAULT_N;
02570     affMrgCtx.BcwIdx[i] = BCW_DEFAULT;
02571   }
02572 
02573   affMrgCtx.numValidMergeCand = 0;
02574   affMrgCtx.maxNumMergeCand = maxNumAffineMergeCand;
02575 
02576   bool sbTmvpEnableFlag = slice.getSPS()->getSbTMVPEnabledFlag()
02577                           && !(slice.getPOC() == slice.getRefPic(REF_PIC_LIST_0, 0)->getPOC() && slice.isIRAP());
02578   bool isAvailableSubPu = false;
02579   if (sbTmvpEnableFlag && slice.getPicHeader()->getEnableTMVPFlag())
02580   {
02581     MergeCtx mrgCtx = *affMrgCtx.mrgCtx;
02582     bool tmpLICFlag = false;
02583 
02584     CHECK( mrgCtx.subPuMvpMiBuf.area() == 0 || !mrgCtx.subPuMvpMiBuf.buf, "Buffer not initialized" );
02585     mrgCtx.subPuMvpMiBuf.fill( MotionInfo() );
02586 
02587     int pos = 0;
02588     // Get spatial MV
02589     const Position posCurLB = pu.Y().bottomLeft();
02590     MotionInfo miLeft;
02591 
02592     //left
02593     const PredictionUnit* puLeft = cs.getPURestricted( posCurLB.offset( -1, 0 ), pu, pu.chType );
02594     const bool isAvailableA1 = puLeft && isDiffMER(pu.lumaPos(), posCurLB.offset(-1, 0), plevel) && pu.cu != puLeft->cu && CU::isInter( *puLeft->cu );
02595     if ( isAvailableA1 )
02596     {
02597       miLeft = puLeft->getMotionInfo( posCurLB.offset( -1, 0 ) );
02598       // get Inter Dir
02599       mrgCtx.interDirNeighbours[pos] = miLeft.interDir;
02600 
02601       // get Mv from Left
02602       mrgCtx.mvFieldNeighbours[pos << 1].setMvField( miLeft.mv[0], miLeft.refIdx[0] );
02603 
02604       if ( slice.isInterB() )
02605       {
02606         mrgCtx.mvFieldNeighbours[(pos << 1) + 1].setMvField( miLeft.mv[1], miLeft.refIdx[1] );
02607       }
02608       pos++;
02609     }
02610 
02611     mrgCtx.numValidMergeCand = pos;
02612 
02613     isAvailableSubPu = getInterMergeSubPuMvpCand(pu, mrgCtx, tmpLICFlag, pos, 0);
02614     if ( isAvailableSubPu )
02615     {
02616       for ( int mvNum = 0; mvNum < 3; mvNum++ )
02617       {
02618         affMrgCtx.mvFieldNeighbours[(affMrgCtx.numValidMergeCand << 1) + 0][mvNum].setMvField( mrgCtx.mvFieldNeighbours[(pos << 1) + 0].mv, mrgCtx.mvFieldNeighbours[(pos << 1) + 0].refIdx );
02619         affMrgCtx.mvFieldNeighbours[(affMrgCtx.numValidMergeCand << 1) + 1][mvNum].setMvField( mrgCtx.mvFieldNeighbours[(pos << 1) + 1].mv, mrgCtx.mvFieldNeighbours[(pos << 1) + 1].refIdx );
02620       }
02621       affMrgCtx.interDirNeighbours[affMrgCtx.numValidMergeCand] = mrgCtx.interDirNeighbours[pos];
02622 
02623       affMrgCtx.affineType[affMrgCtx.numValidMergeCand] = AFFINE_MODEL_NUM;
02624       affMrgCtx.mergeType[affMrgCtx.numValidMergeCand] = MRG_TYPE_SUBPU_ATMVP;
02625       if ( affMrgCtx.numValidMergeCand == mrgCandIdx )
02626       {
02627         return;
02628       }
02629 
02630       affMrgCtx.numValidMergeCand++;
02631 
02632       // early termination
02633       if ( affMrgCtx.numValidMergeCand == maxNumAffineMergeCand )
02634       {
02635         return;
02636       }
02637     }
02638   }
02639 
02640   if ( slice.getSPS()->getUseAffine() )
02641   {
02643     const PredictionUnit* npu[5];
02644     int numAffNeighLeft = getAvailableAffineNeighboursForLeftPredictor( pu, npu );
02645     int numAffNeigh = getAvailableAffineNeighboursForAbovePredictor( pu, npu, numAffNeighLeft );
02646     for ( int idx = 0; idx < numAffNeigh; idx++ )
02647     {
02648       // derive Mv from Neigh affine PU
02649       Mv cMv[2][3];
02650       const PredictionUnit* puNeigh = npu[idx];
02651       pu.cu->affineType = puNeigh->cu->affineType;
02652       if ( puNeigh->interDir != 2 )
02653       {
02654         xInheritedAffineMv( pu, puNeigh, REF_PIC_LIST_0, cMv[0] );
02655       }
02656       if ( slice.isInterB() )
02657       {
02658         if ( puNeigh->interDir != 1 )
02659         {
02660           xInheritedAffineMv( pu, puNeigh, REF_PIC_LIST_1, cMv[1] );
02661         }
02662       }
02663 
02664       for ( int mvNum = 0; mvNum < 3; mvNum++ )
02665       {
02666         affMrgCtx.mvFieldNeighbours[(affMrgCtx.numValidMergeCand << 1) + 0][mvNum].setMvField( cMv[0][mvNum], puNeigh->refIdx[0] );
02667         affMrgCtx.mvFieldNeighbours[(affMrgCtx.numValidMergeCand << 1) + 1][mvNum].setMvField( cMv[1][mvNum], puNeigh->refIdx[1] );
02668       }
02669       affMrgCtx.interDirNeighbours[affMrgCtx.numValidMergeCand] = puNeigh->interDir;
02670       affMrgCtx.affineType[affMrgCtx.numValidMergeCand] = (EAffineModel)(puNeigh->cu->affineType);
02671       affMrgCtx.BcwIdx[affMrgCtx.numValidMergeCand] = puNeigh->cu->BcwIdx;
02672 
02673       if ( affMrgCtx.numValidMergeCand == mrgCandIdx )
02674       {
02675         return;
02676       }
02677 
02678       // early termination
02679       affMrgCtx.numValidMergeCand++;
02680       if ( affMrgCtx.numValidMergeCand == maxNumAffineMergeCand )
02681       {
02682         return;
02683       }
02684     }
02686 
02688     {
02689       MotionInfo mi[4];
02690       bool isAvailable[4] = { false };
02691 
02692       int8_t neighBcw[2] = { BCW_DEFAULT, BCW_DEFAULT };
02693       // control point: LT B2->B3->A2
02694       const Position posLT[3] = { pu.Y().topLeft().offset( -1, -1 ), pu.Y().topLeft().offset( 0, -1 ), pu.Y().topLeft().offset( -1, 0 ) };
02695       for ( int i = 0; i < 3; i++ )
02696       {
02697         const Position pos = posLT[i];
02698         const PredictionUnit* puNeigh = cs.getPURestricted( pos, pu, pu.chType );
02699 
02700         if (puNeigh && CU::isInter(*puNeigh->cu) && PU::isDiffMER(pu.lumaPos(), pos, plevel))
02701         {
02702           isAvailable[0] = true;
02703           mi[0] = puNeigh->getMotionInfo( pos );
02704           neighBcw[0] = puNeigh->cu->BcwIdx;
02705           break;
02706         }
02707       }
02708 
02709       // control point: RT B1->B0
02710       const Position posRT[2] = { pu.Y().topRight().offset( 0, -1 ), pu.Y().topRight().offset( 1, -1 ) };
02711       for ( int i = 0; i < 2; i++ )
02712       {
02713         const Position pos = posRT[i];
02714         const PredictionUnit* puNeigh = cs.getPURestricted( pos, pu, pu.chType );
02715 
02716         if (puNeigh && CU::isInter(*puNeigh->cu) && PU::isDiffMER(pu.lumaPos(), pos, plevel))
02717         {
02718           isAvailable[1] = true;
02719           mi[1] = puNeigh->getMotionInfo( pos );
02720           neighBcw[1] = puNeigh->cu->BcwIdx;
02721           break;
02722         }
02723       }
02724 
02725       // control point: LB A1->A0
02726       const Position posLB[2] = { pu.Y().bottomLeft().offset( -1, 0 ), pu.Y().bottomLeft().offset( -1, 1 ) };
02727       for ( int i = 0; i < 2; i++ )
02728       {
02729         const Position pos = posLB[i];
02730         const PredictionUnit* puNeigh = cs.getPURestricted( pos, pu, pu.chType );
02731 
02732         if (puNeigh && CU::isInter(*puNeigh->cu) && PU::isDiffMER(pu.lumaPos(), pos, plevel))
02733         {
02734           isAvailable[2] = true;
02735           mi[2] = puNeigh->getMotionInfo( pos );
02736           break;
02737         }
02738       }
02739 
02740       // control point: RB
02741       if ( slice.getPicHeader()->getEnableTMVPFlag() )
02742       {
02743         //>> MTK colocated-RightBottom
02744         // offset the pos to be sure to "point" to the same position the uiAbsPartIdx would've pointed to
02745         Position posRB = pu.Y().bottomRight().offset( -3, -3 );
02746 
02747         const PreCalcValues& pcv = *cs.pcv;
02748         Position posC0;
02749         bool C0Avail = false;
02750 
02751         bool boundaryCond = ((posRB.x + pcv.minCUWidth) < pcv.lumaWidth) && ((posRB.y + pcv.minCUHeight) < pcv.lumaHeight);
02752         const SubPic &curSubPic = pu.cs->slice->getPPS()->getSubPicFromPos(pu.lumaPos());
02753         if (curSubPic.getTreatedAsPicFlag())
02754         {
02755           boundaryCond = ((posRB.x + pcv.minCUWidth) <= curSubPic.getSubPicRight() &&
02756             (posRB.y + pcv.minCUHeight) <= curSubPic.getSubPicBottom());
02757         }
02758         if (boundaryCond)
02759         {
02760           int posYInCtu = posRB.y & pcv.maxCUHeightMask;
02761           if (posYInCtu + 4 < pcv.maxCUHeight)
02762           {
02763             posC0 = posRB.offset(4, 4);
02764             C0Avail = true;
02765           }
02766         }
02767 
02768         Mv        cColMv;
02769         int       refIdx = 0;
02770         bool      bExistMV = C0Avail && getColocatedMVP( pu, REF_PIC_LIST_0, posC0, cColMv, refIdx, false );
02771         if ( bExistMV )
02772         {
02773           mi[3].mv[0] = cColMv;
02774           mi[3].refIdx[0] = refIdx;
02775           mi[3].interDir = 1;
02776           isAvailable[3] = true;
02777         }
02778 
02779         if ( slice.isInterB() )
02780         {
02781           bExistMV = C0Avail && getColocatedMVP( pu, REF_PIC_LIST_1, posC0, cColMv, refIdx, false );
02782           if ( bExistMV )
02783           {
02784             mi[3].mv[1] = cColMv;
02785             mi[3].refIdx[1] = refIdx;
02786             mi[3].interDir |= 2;
02787             isAvailable[3] = true;
02788           }
02789         }
02790       }
02791 
02792       //-------------------  insert model  -------------------//
02793       int order[6] = { 0, 1, 2, 3, 4, 5 };
02794       int modelNum = 6;
02795       int model[6][4] = {
02796         { 0, 1, 2 },          // 0:  LT, RT, LB
02797         { 0, 1, 3 },          // 1:  LT, RT, RB
02798         { 0, 2, 3 },          // 2:  LT, LB, RB
02799         { 1, 2, 3 },          // 3:  RT, LB, RB
02800         { 0, 1 },             // 4:  LT, RT
02801         { 0, 2 },             // 5:  LT, LB
02802       };
02803 
02804       int verNum[6] = { 3, 3, 3, 3, 2, 2 };
02805       int startIdx = pu.cs->sps->getUseAffineType() ? 0 : 4;
02806       for ( int idx = startIdx; idx < modelNum; idx++ )
02807       {
02808         int modelIdx = order[idx];
02809         getAffineControlPointCand(pu, mi, isAvailable, model[modelIdx], ((modelIdx == 3) ? neighBcw[1] : neighBcw[0]), modelIdx, verNum[modelIdx], affMrgCtx);
02810         if ( affMrgCtx.numValidMergeCand != 0 && affMrgCtx.numValidMergeCand - 1 == mrgCandIdx )
02811         {
02812           return;
02813         }
02814 
02815         // early termination
02816         if ( affMrgCtx.numValidMergeCand == maxNumAffineMergeCand )
02817         {
02818           return;
02819         }
02820       }
02821     }
02823   }
02824 
02826   int cnt = affMrgCtx.numValidMergeCand;
02827   while ( cnt < maxNumAffineMergeCand )
02828   {
02829     for ( int mvNum = 0; mvNum < 3; mvNum++ )
02830     {
02831       affMrgCtx.mvFieldNeighbours[(cnt << 1) + 0][mvNum].setMvField( Mv( 0, 0 ), 0 );
02832     }
02833     affMrgCtx.interDirNeighbours[cnt] = 1;
02834 
02835     if ( slice.isInterB() )
02836     {
02837       for ( int mvNum = 0; mvNum < 3; mvNum++ )
02838       {
02839         affMrgCtx.mvFieldNeighbours[(cnt << 1) + 1][mvNum].setMvField( Mv( 0, 0 ), 0 );
02840       }
02841       affMrgCtx.interDirNeighbours[cnt] = 3;
02842     }
02843     affMrgCtx.affineType[cnt] = AFFINEMODEL_4PARAM;
02844 
02845     if ( cnt == mrgCandIdx )
02846     {
02847       return;
02848     }
02849     cnt++;
02850     affMrgCtx.numValidMergeCand++;
02851   }
02852 }
