02854 void PU::setAllAffineMvField( PredictionUnit &pu, MvField *mvField, RefPicList eRefList )
02855 {
02856   // Set Mv
02857   Mv mv[3];
02858   for ( int i = 0; i < 3; i++ )
02859   {
02860     mv[i] = mvField[i].mv;
02861   }
02862   setAllAffineMv( pu, mv[0], mv[1], mv[2], eRefList );
02863 
02864   // Set RefIdx
02865   CHECK( mvField[0].refIdx != mvField[1].refIdx || mvField[0].refIdx != mvField[2].refIdx, "Affine mv corners don't have the same refIdx." );
02866   pu.refIdx[eRefList] = mvField[0].refIdx;
02867 }
02868 
02869 void PU::setAllAffineMv(PredictionUnit& pu, Mv affLT, Mv affRT, Mv affLB, RefPicList eRefList, bool clipCPMVs)
02870 {
02871   int width  = pu.Y().width;
02872   int shift = MAX_CU_DEPTH;
02873   if (clipCPMVs)
02874   {
02875     affLT.mvCliptoStorageBitDepth();
02876     affRT.mvCliptoStorageBitDepth();
02877     if (pu.cu->affineType == AFFINEMODEL_6PARAM)
02878     {
02879       affLB.mvCliptoStorageBitDepth();
02880     }
02881   }
02882   int deltaMvHorX, deltaMvHorY, deltaMvVerX, deltaMvVerY;
02883   deltaMvHorX = (affRT - affLT).getHor() << (shift - floorLog2(width));
02884   deltaMvHorY = (affRT - affLT).getVer() << (shift - floorLog2(width));
02885   int height = pu.Y().height;
02886   if ( pu.cu->affineType == AFFINEMODEL_6PARAM )
02887   {
02888     deltaMvVerX = (affLB - affLT).getHor() << (shift - floorLog2(height));
02889     deltaMvVerY = (affLB - affLT).getVer() << (shift - floorLog2(height));
02890   }
02891   else
02892   {
02893     deltaMvVerX = -deltaMvHorY;
02894     deltaMvVerY = deltaMvHorX;
02895   }
02896 
02897   int mvScaleHor = affLT.getHor() << shift;
02898   int mvScaleVer = affLT.getVer() << shift;
02899 
02900   int blockWidth = AFFINE_MIN_BLOCK_SIZE;
02901   int blockHeight = AFFINE_MIN_BLOCK_SIZE;
02902   const int halfBW = blockWidth >> 1;
02903   const int halfBH = blockHeight >> 1;
02904 
02905   MotionBuf mb = pu.getMotionBuf();
02906   int mvScaleTmpHor, mvScaleTmpVer;
02907   const bool subblkMVSpreadOverLimit = InterPrediction::isSubblockVectorSpreadOverLimit( deltaMvHorX, deltaMvHorY, deltaMvVerX, deltaMvVerY, pu.interDir );
02908   for ( int h = 0; h < pu.Y().height; h += blockHeight )
02909   {
02910     for ( int w = 0; w < pu.Y().width; w += blockWidth )
02911     {
02912       if ( !subblkMVSpreadOverLimit )
02913       {
02914         mvScaleTmpHor = mvScaleHor + deltaMvHorX * (halfBW + w) + deltaMvVerX * (halfBH + h);
02915         mvScaleTmpVer = mvScaleVer + deltaMvHorY * (halfBW + w) + deltaMvVerY * (halfBH + h);
02916       }
02917       else
02918       {
02919         mvScaleTmpHor = mvScaleHor + deltaMvHorX * ( pu.Y().width >> 1 ) + deltaMvVerX * ( pu.Y().height >> 1 );
02920         mvScaleTmpVer = mvScaleVer + deltaMvHorY * ( pu.Y().width >> 1 ) + deltaMvVerY * ( pu.Y().height >> 1 );
02921       }
02922       roundAffineMv( mvScaleTmpHor, mvScaleTmpVer, shift );
02923       Mv curMv(mvScaleTmpHor, mvScaleTmpVer);
02924       curMv.clipToStorageBitDepth();
02925 
02926       for ( int y = (h >> MIN_CU_LOG2); y < ((h + blockHeight) >> MIN_CU_LOG2); y++ )
02927       {
02928         for ( int x = (w >> MIN_CU_LOG2); x < ((w + blockWidth) >> MIN_CU_LOG2); x++ )
02929         {
02930           mb.at(x, y).mv[eRefList] = curMv;
02931         }
02932       }
02933     }
02934   }
02935 
02936   pu.mvAffi[eRefList][0] = affLT;
02937   pu.mvAffi[eRefList][1] = affRT;
02938   pu.mvAffi[eRefList][2] = affLB;
02939 }
02940 
02941 void clipColPos(int& posX, int& posY, const PredictionUnit& pu)
02942 {
02943   Position puPos = pu.lumaPos();
02944   int log2CtuSize = floorLog2(pu.cs->sps->getCTUSize());
02945   int ctuX = ((puPos.x >> log2CtuSize) << log2CtuSize);
02946   int ctuY = ((puPos.y >> log2CtuSize) << log2CtuSize);
02947   int horMax;
02948   const SubPic &curSubPic = pu.cu->slice->getPPS()->getSubPicFromPos(puPos);
02949   if (curSubPic.getTreatedAsPicFlag())
02950   {
02951     horMax = std::min((int)curSubPic.getSubPicRight(), ctuX + (int)pu.cs->sps->getCTUSize() + 3);
02952   }
02953   else
02954   {
02955     horMax = std::min((int)pu.cs->pps->getPicWidthInLumaSamples() - 1, ctuX + (int)pu.cs->sps->getCTUSize() + 3);
02956   }
02957   int horMin = std::max((int)0, ctuX);
02958   int verMax = std::min( (int)pu.cs->pps->getPicHeightInLumaSamples() - 1, ctuY + (int)pu.cs->sps->getCTUSize() - 1 );
02959   int verMin = std::max((int)0, ctuY);
02960 
02961   posX = std::min(horMax, std::max(horMin, posX));
02962   posY = std::min(verMax, std::max(verMin, posY));
02963 }
02964 
02965 bool PU::getInterMergeSubPuMvpCand(const PredictionUnit &pu, MergeCtx& mrgCtx, bool& LICFlag, const int count
02966   , int mmvdList
02967 )
02968 {
02969   const Slice   &slice = *pu.cs->slice;
02970   const unsigned scale = 4 * std::max<int>(1, 4 * AMVP_DECIMATION_FACTOR / 4);
02971   const unsigned mask = ~(scale - 1);
02972 
02973   const Picture *pColPic = slice.getRefPic(RefPicList(slice.isInterB() ? 1 - slice.getColFromL0Flag() : 0), slice.getColRefIdx());
02974   Mv cTMv;
02975 
02976   if ( count )
02977   {
02978     if ( (mrgCtx.interDirNeighbours[0] & (1 << REF_PIC_LIST_0)) && slice.getRefPic( REF_PIC_LIST_0, mrgCtx.mvFieldNeighbours[REF_PIC_LIST_0].refIdx ) == pColPic )
02979     {
02980       cTMv = mrgCtx.mvFieldNeighbours[REF_PIC_LIST_0].mv;
02981     }
02982     else if ( slice.isInterB() && (mrgCtx.interDirNeighbours[0] & (1 << REF_PIC_LIST_1)) && slice.getRefPic( REF_PIC_LIST_1, mrgCtx.mvFieldNeighbours[REF_PIC_LIST_1].refIdx ) == pColPic )
02983     {
02984       cTMv = mrgCtx.mvFieldNeighbours[REF_PIC_LIST_1].mv;
02985     }
02986   }
02987 
02991 
02992   Mv cTempVector = cTMv;
02993   bool  tempLICFlag = false;
02994 
02995   // compute the location of the current PU
02996   Position puPos = pu.lumaPos();
02997   Size puSize = pu.lumaSize();
02998   int numPartLine = std::max(puSize.width >> ATMVP_SUB_BLOCK_SIZE, 1u);
02999   int numPartCol = std::max(puSize.height >> ATMVP_SUB_BLOCK_SIZE, 1u);
03000   int puHeight = numPartCol == 1 ? puSize.height : 1 << ATMVP_SUB_BLOCK_SIZE;
03001   int puWidth = numPartLine == 1 ? puSize.width : 1 << ATMVP_SUB_BLOCK_SIZE;
03002 
03003   Mv cColMv;
03004   int refIdx = 0;
03005   // use coldir.
03006   bool     bBSlice = slice.isInterB();
03007 
03008   Position centerPos;
03009 
03010   bool found = false;
03011   cTempVector = cTMv;
03012 
03013   cTempVector.changePrecision(MV_PRECISION_SIXTEENTH, MV_PRECISION_INT);
03014   int tempX = cTempVector.getHor();
03015   int tempY = cTempVector.getVer();
03016 
03017   centerPos.x = puPos.x + (puSize.width >> 1) + tempX;
03018   centerPos.y = puPos.y + (puSize.height >> 1) + tempY;
03019 
03020   clipColPos(centerPos.x, centerPos.y, pu);
03021 
03022   centerPos = Position{ PosType(centerPos.x & mask), PosType(centerPos.y & mask) };
03023 
03024   // derivation of center motion parameters from the collocated CU
03025   const MotionInfo &mi = pColPic->cs->getMotionInfo(centerPos);
03026 
03027   if (mi.isInter && mi.isIBCmot == false)
03028   {
03029     mrgCtx.interDirNeighbours[count] = 0;
03030 
03031     for (unsigned currRefListId = 0; currRefListId < (bBSlice ? 2 : 1); currRefListId++)
03032     {
03033       RefPicList  currRefPicList = RefPicList(currRefListId);
03034 
03035       if (getColocatedMVP(pu, currRefPicList, centerPos, cColMv, refIdx, true))
03036       {
03037         // set as default, for further motion vector field spanning
03038         mrgCtx.mvFieldNeighbours[(count << 1) + currRefListId].setMvField(cColMv, 0);
03039         mrgCtx.interDirNeighbours[count] |= (1 << currRefListId);
03040         LICFlag = tempLICFlag;
03041         mrgCtx.BcwIdx[count] = BCW_DEFAULT;
03042         found = true;
03043       }
03044       else
03045       {
03046         mrgCtx.mvFieldNeighbours[(count << 1) + currRefListId].setMvField(Mv(), NOT_VALID);
03047         mrgCtx.interDirNeighbours[count] &= ~(1 << currRefListId);
03048       }
03049     }
03050   }
03051 
03052   if (!found)
03053   {
03054     return false;
03055   }
03056   if (mmvdList != 1)
03057   {
03058     int xOff = (puWidth >> 1) + tempX;
03059     int yOff = (puHeight >> 1) + tempY;
03060 
03061     MotionBuf &mb = mrgCtx.subPuMvpMiBuf;
03062 
03063     const bool isBiPred = isBipredRestriction(pu);
03064 
03065     for (int y = puPos.y; y < puPos.y + puSize.height; y += puHeight)
03066     {
03067       for (int x = puPos.x; x < puPos.x + puSize.width; x += puWidth)
03068       {
03069         Position colPos{ x + xOff, y + yOff };
03070 
03071         clipColPos(colPos.x, colPos.y, pu);
03072 
03073         colPos = Position{ PosType(colPos.x & mask), PosType(colPos.y & mask) };
03074 
03075         const MotionInfo &colMi = pColPic->cs->getMotionInfo(colPos);
03076 
03077         MotionInfo mi;
03078 
03079         found       = false;
03080         mi.isInter  = true;
03081         mi.sliceIdx = slice.getIndependentSliceIdx();
03082         mi.isIBCmot = false;
03083         if (colMi.isInter && colMi.isIBCmot == false)
03084         {
03085           for (unsigned currRefListId = 0; currRefListId < (bBSlice ? 2 : 1); currRefListId++)
03086           {
03087             RefPicList currRefPicList = RefPicList(currRefListId);
03088             if (getColocatedMVP(pu, currRefPicList, colPos, cColMv, refIdx, true))
03089             {
03090               mi.refIdx[currRefListId] = 0;
03091               mi.mv[currRefListId]     = cColMv;
03092               found                    = true;
03093             }
03094           }
03095         }
03096         if (!found)
03097         {
03098           mi.mv[0]     = mrgCtx.mvFieldNeighbours[(count << 1) + 0].mv;
03099           mi.mv[1]     = mrgCtx.mvFieldNeighbours[(count << 1) + 1].mv;
03100           mi.refIdx[0] = mrgCtx.mvFieldNeighbours[(count << 1) + 0].refIdx;
03101           mi.refIdx[1] = mrgCtx.mvFieldNeighbours[(count << 1) + 1].refIdx;
03102         }
03103 
03104         mi.interDir = (mi.refIdx[0] != -1 ? 1 : 0) + (mi.refIdx[1] != -1 ? 2 : 0);
03105 
03106         if (isBiPred && mi.interDir == 3)
03107         {
03108           mi.interDir  = 1;
03109           mi.mv[1]     = Mv();
03110           mi.refIdx[1] = NOT_VALID;
03111         }
03112 
03113         mb.subBuf(g_miScaling.scale(Position{ x, y } - pu.lumaPos()), g_miScaling.scale(Size(puWidth, puHeight)))
03114           .fill(mi);
03115       }
03116     }
03117   }
03118   return true;
03119 }
03120 
03121 void PU::spanMotionInfo( PredictionUnit &pu, const MergeCtx &mrgCtx )
03122 {
03123   MotionBuf mb = pu.getMotionBuf();
03124 
03125   if (!pu.mergeFlag || pu.mergeType == MRG_TYPE_DEFAULT_N || pu.mergeType == MRG_TYPE_IBC)
03126   {
03127     MotionInfo mi;
03128 
03129     mi.isInter = !CU::isIntra(*pu.cu);
03130     mi.isIBCmot = CU::isIBC(*pu.cu);
03131     mi.sliceIdx = pu.cu->slice->getIndependentSliceIdx();
03132 
03133     if( mi.isInter )
03134     {
03135       mi.interDir = pu.interDir;
03136       mi.useAltHpelIf = pu.cu->imv == IMV_HPEL;
03137 
03138       for( int i = 0; i < NUM_REF_PIC_LIST_01; i++ )
03139       {
03140         mi.mv[i]     = pu.mv[i];
03141         mi.refIdx[i] = pu.refIdx[i];
03142       }
03143       if (mi.isIBCmot)
03144       {
03145         mi.bv = pu.bv;
03146       }
03147     }
03148 
03149     if( pu.cu->affine )
03150     {
03151       for( int y = 0; y < mb.height; y++ )
03152       {
03153         for( int x = 0; x < mb.width; x++ )
03154         {
03155           MotionInfo &dest = mb.at( x, y );
03156           dest.isInter  = mi.isInter;
03157           dest.isIBCmot = false;
03158           dest.interDir = mi.interDir;
03159           dest.sliceIdx = mi.sliceIdx;
03160           for( int i = 0; i < NUM_REF_PIC_LIST_01; i++ )
03161           {
03162             if( mi.refIdx[i] == -1 )
03163             {
03164               dest.mv[i] = Mv();
03165             }
03166             dest.refIdx[i] = mi.refIdx[i];
03167           }
03168         }
03169       }
03170     }
03171     else
03172     {
03173       mb.fill( mi );
03174     }
03175   }
03176   else if (pu.mergeType == MRG_TYPE_SUBPU_ATMVP)
03177   {
03178     CHECK(mrgCtx.subPuMvpMiBuf.area() == 0 || !mrgCtx.subPuMvpMiBuf.buf, "Buffer not initialized");
03179     mb.copyFrom(mrgCtx.subPuMvpMiBuf);
03180   }
03181   else
03182   {
03183     if( isBipredRestriction( pu ) )
03184     {
03185       for( int y = 0; y < mb.height; y++ )
03186       {
03187         for( int x = 0; x < mb.width; x++ )
03188         {
03189           MotionInfo &mi = mb.at( x, y );
03190           if( mi.interDir == 3 )
03191           {
03192             mi.interDir  = 1;
03193             mi.mv    [1] = Mv();
03194             mi.refIdx[1] = NOT_VALID;
03195           }
03196         }
03197       }
03198     }
03199   }
03200 }
03201 
03202 void PU::applyImv( PredictionUnit& pu, MergeCtx &mrgCtx, InterPrediction *interPred )
03203 {
03204   if( !pu.mergeFlag )
03205   {
03206     if( pu.interDir != 2 /* PRED_L1 */ )
03207     {
03208       pu.mvd[0].changeTransPrecAmvr2Internal(pu.cu->imv);
03209       unsigned mvp_idx = pu.mvpIdx[0];
03210       AMVPInfo amvpInfo;
03211       if (CU::isIBC(*pu.cu))
03212       {
03213         PU::fillIBCMvpCand(pu, amvpInfo);
03214       }
03215       else
03216       PU::fillMvpCand(pu, REF_PIC_LIST_0, pu.refIdx[0], amvpInfo);
03217       pu.mvpNum[0] = amvpInfo.numCand;
03218       pu.mvpIdx[0] = mvp_idx;
03219       pu.mv    [0] = amvpInfo.mvCand[mvp_idx] + pu.mvd[0];
03220       pu.mv[0].mvCliptoStorageBitDepth();
03221     }
03222 
03223     if (pu.interDir != 1 /* PRED_L0 */)
03224     {
03225       if( !( pu.cu->cs->picHeader->getMvdL1ZeroFlag() && pu.interDir == 3 ) && pu.cu->imv )/* PRED_BI */
03226       {
03227         pu.mvd[1].changeTransPrecAmvr2Internal(pu.cu->imv);
03228       }
03229       unsigned mvp_idx = pu.mvpIdx[1];
03230       AMVPInfo amvpInfo;
03231       PU::fillMvpCand(pu, REF_PIC_LIST_1, pu.refIdx[1], amvpInfo);
03232       pu.mvpNum[1] = amvpInfo.numCand;
03233       pu.mvpIdx[1] = mvp_idx;
03234       pu.mv    [1] = amvpInfo.mvCand[mvp_idx] + pu.mvd[1];
03235       pu.mv[1].mvCliptoStorageBitDepth();
03236     }
03237   }
03238   else
03239   {
03240     // this function is never called for merge
03241     THROW("unexpected");
03242     PU::getInterMergeCandidates(pu, mrgCtx, 0);
03243 
03244     mrgCtx.setMergeInfo( pu, pu.mergeIdx );
03245   }
03246 
03247   PU::spanMotionInfo( pu, mrgCtx );
03248 }
