03250 
03251 bool PU::isBiPredFromDifferentDirEqDistPoc(const PredictionUnit& pu)
03252 {
03253   if (pu.refIdx[0] >= 0 && pu.refIdx[1] >= 0)
03254   {
03255     if (pu.cu->slice->getRefPic(REF_PIC_LIST_0, pu.refIdx[0])->longTerm
03256       || pu.cu->slice->getRefPic(REF_PIC_LIST_1, pu.refIdx[1])->longTerm)
03257     {
03258       return false;
03259     }
03260     const int poc0 = pu.cu->slice->getRefPOC(REF_PIC_LIST_0, pu.refIdx[0]);
03261     const int poc1 = pu.cu->slice->getRefPOC(REF_PIC_LIST_1, pu.refIdx[1]);
03262     const int poc = pu.cu->slice->getPOC();
03263     if ((poc - poc0)*(poc - poc1) < 0)
03264     {
03265       if (abs(poc - poc0) == abs(poc - poc1))
03266       {
03267         return true;
03268       }
03269     }
03270   }
03271   return false;
03272 }
