03287 
03288 void PU::getGeoMergeCandidates( const PredictionUnit &pu, MergeCtx& geoMrgCtx )
03289 {
03290   MergeCtx tmpMergeCtx;
03291 
03292   const uint32_t maxNumMergeCand = pu.cs->sps->getMaxNumMergeCand();
03293   geoMrgCtx.numValidMergeCand = 0;
03294 
03295   for (int32_t i = 0; i < GEO_MAX_NUM_UNI_CANDS; i++)
03296   {
03297     geoMrgCtx.BcwIdx[i] = BCW_DEFAULT;
03298     geoMrgCtx.interDirNeighbours[i] = 0;
03299     geoMrgCtx.mrgTypeNeighbours[i] = MRG_TYPE_DEFAULT_N;
03300     geoMrgCtx.mvFieldNeighbours[(i << 1)].refIdx = NOT_VALID;
03301     geoMrgCtx.mvFieldNeighbours[(i << 1) + 1].refIdx = NOT_VALID;
03302     geoMrgCtx.mvFieldNeighbours[(i << 1)].mv = Mv();
03303     geoMrgCtx.mvFieldNeighbours[(i << 1) + 1].mv = Mv();
03304     geoMrgCtx.useAltHpelIf[i] = false;
03305   }
03306 
03307   PU::getInterMergeCandidates(pu, tmpMergeCtx, 0);
03308 
03309   for (int32_t i = 0; i < maxNumMergeCand; i++)
03310   {
03311     int parity = i & 1;
03312     if( tmpMergeCtx.interDirNeighbours[i] & (0x01 + parity) )
03313     {
03314       geoMrgCtx.interDirNeighbours[geoMrgCtx.numValidMergeCand] = 1 + parity;
03315       geoMrgCtx.mrgTypeNeighbours[geoMrgCtx.numValidMergeCand] = MRG_TYPE_DEFAULT_N;
03316       geoMrgCtx.mvFieldNeighbours[(geoMrgCtx.numValidMergeCand << 1) + !parity].mv = Mv(0, 0);
03317       geoMrgCtx.mvFieldNeighbours[(geoMrgCtx.numValidMergeCand << 1) + parity].mv = tmpMergeCtx.mvFieldNeighbours[(i << 1) + parity].mv;
03318       geoMrgCtx.mvFieldNeighbours[(geoMrgCtx.numValidMergeCand << 1) + !parity].refIdx = -1;
03319       geoMrgCtx.mvFieldNeighbours[(geoMrgCtx.numValidMergeCand << 1) + parity].refIdx = tmpMergeCtx.mvFieldNeighbours[(i << 1) + parity].refIdx;
03320       geoMrgCtx.numValidMergeCand++;
03321       if (geoMrgCtx.numValidMergeCand == GEO_MAX_NUM_UNI_CANDS)
03322       {
03323         return;
03324       }
03325       continue;
03326     }
03327 
03328     if (tmpMergeCtx.interDirNeighbours[i] & (0x02 - parity))
03329     {
03330       geoMrgCtx.interDirNeighbours[geoMrgCtx.numValidMergeCand] = 2 - parity;
03331       geoMrgCtx.mrgTypeNeighbours[geoMrgCtx.numValidMergeCand] = MRG_TYPE_DEFAULT_N;
03332       geoMrgCtx.mvFieldNeighbours[(geoMrgCtx.numValidMergeCand << 1) + !parity].mv = tmpMergeCtx.mvFieldNeighbours[(i << 1) + !parity].mv;
03333       geoMrgCtx.mvFieldNeighbours[(geoMrgCtx.numValidMergeCand << 1) + parity].mv = Mv(0, 0);
03334       geoMrgCtx.mvFieldNeighbours[(geoMrgCtx.numValidMergeCand << 1) + !parity].refIdx = tmpMergeCtx.mvFieldNeighbours[(i << 1) + !parity].refIdx;
03335       geoMrgCtx.mvFieldNeighbours[(geoMrgCtx.numValidMergeCand << 1) + parity].refIdx = -1;
03336       geoMrgCtx.numValidMergeCand++;
03337       if (geoMrgCtx.numValidMergeCand == GEO_MAX_NUM_UNI_CANDS)
03338       {
03339         return;
03340       }
03341     }
03342   }
03343 }
03344 
03345 void PU::spanGeoMotionInfo( PredictionUnit &pu, MergeCtx &geoMrgCtx, const uint8_t splitDir, const uint8_t candIdx0, const uint8_t candIdx1)
03346 {
03347   pu.geoSplitDir  = splitDir;
03348   pu.geoMergeIdx0 = candIdx0;
03349   pu.geoMergeIdx1 = candIdx1;
03350   MotionBuf mb = pu.getMotionBuf();
03351 
03352   MotionInfo biMv;
03353   biMv.isInter  = true;
03354   biMv.sliceIdx = pu.cs->slice->getIndependentSliceIdx();
03355 
03356   if( geoMrgCtx.interDirNeighbours[candIdx0] == 1 && geoMrgCtx.interDirNeighbours[candIdx1] == 2 )
03357   {
03358     biMv.interDir  = 3;
03359     biMv.mv[0]     = geoMrgCtx.mvFieldNeighbours[ candIdx0 << 1     ].mv;
03360     biMv.mv[1]     = geoMrgCtx.mvFieldNeighbours[(candIdx1 << 1) + 1].mv;
03361     biMv.refIdx[0] = geoMrgCtx.mvFieldNeighbours[ candIdx0 << 1     ].refIdx;
03362     biMv.refIdx[1] = geoMrgCtx.mvFieldNeighbours[(candIdx1 << 1) + 1].refIdx;
03363   }
03364   else if( geoMrgCtx.interDirNeighbours[candIdx0] == 2 && geoMrgCtx.interDirNeighbours[candIdx1] == 1 )
03365   {
03366     biMv.interDir  = 3;
03367     biMv.mv[0]     = geoMrgCtx.mvFieldNeighbours[ candIdx1 << 1     ].mv;
03368     biMv.mv[1]     = geoMrgCtx.mvFieldNeighbours[(candIdx0 << 1) + 1].mv;
03369     biMv.refIdx[0] = geoMrgCtx.mvFieldNeighbours[ candIdx1 << 1     ].refIdx;
03370     biMv.refIdx[1] = geoMrgCtx.mvFieldNeighbours[(candIdx0 << 1) + 1].refIdx;
03371   }
03372   else if( geoMrgCtx.interDirNeighbours[candIdx0] == 1 && geoMrgCtx.interDirNeighbours[candIdx1] == 1 )
03373   {
03374     biMv.interDir = 1;
03375     biMv.mv[0] = geoMrgCtx.mvFieldNeighbours[candIdx1 << 1].mv;
03376     biMv.mv[1] = Mv(0, 0);
03377     biMv.refIdx[0] = geoMrgCtx.mvFieldNeighbours[candIdx1 << 1].refIdx;
03378     biMv.refIdx[1] = -1;
03379   }
03380   else if( geoMrgCtx.interDirNeighbours[candIdx0] == 2 && geoMrgCtx.interDirNeighbours[candIdx1] == 2 )
03381   {
03382     biMv.interDir = 2;
03383     biMv.mv[0] = Mv(0, 0);
03384     biMv.mv[1] = geoMrgCtx.mvFieldNeighbours[(candIdx1 << 1) + 1].mv;
03385     biMv.refIdx[0] = -1;
03386     biMv.refIdx[1] = geoMrgCtx.mvFieldNeighbours[(candIdx1 << 1) + 1].refIdx;
03387   }
03388 
03389   int16_t angle = g_GeoParams[splitDir][0];
03390   int tpmMask = 0;
03391   int lookUpY = 0, motionIdx = 0;
03392   bool isFlip = angle >= 13 && angle <= 27;
03393   int distanceIdx = g_GeoParams[splitDir][1];
03394   int distanceX = angle;
03395   int distanceY = (distanceX + (GEO_NUM_ANGLES >> 2)) % GEO_NUM_ANGLES;
03396   int offsetX = (-(int)pu.lwidth()) >> 1;
03397   int offsetY = (-(int)pu.lheight()) >> 1;
03398   if (distanceIdx > 0)
03399   {
03400     if (angle % 16 == 8 || (angle % 16 != 0 && pu.lheight() >= pu.lwidth()))
03401     {
03402       offsetY += angle < 16 ? ((distanceIdx * pu.lheight()) >> 3) : -(int)((distanceIdx * pu.lheight()) >> 3);
03403     }
03404     else
03405     {
03406       offsetX += angle < 16 ? ((distanceIdx * pu.lwidth()) >> 3) : -(int)((distanceIdx * pu.lwidth()) >> 3);
03407     }
03408   }
03409   for (int y = 0; y < mb.height; y++)
03410   {
03411     lookUpY = (((4 * y + offsetY) << 1) + 5) * g_Dis[distanceY];
03412     for (int x = 0; x < mb.width; x++)
03413     {
03414       motionIdx = (((4 * x + offsetX) << 1) + 5) * g_Dis[distanceX] + lookUpY;
03415       tpmMask = abs(motionIdx) < 32 ? 2 : (motionIdx <= 0 ? (1 - isFlip) : isFlip);
03416       if (tpmMask == 2)
03417       {
03418         mb.at(x, y).isInter = true;
03419         mb.at(x, y).interDir = biMv.interDir;
03420         mb.at(x, y).refIdx[0] = biMv.refIdx[0];
03421         mb.at(x, y).refIdx[1] = biMv.refIdx[1];
03422         mb.at(x, y).mv[0] = biMv.mv[0];
03423         mb.at(x, y).mv[1] = biMv.mv[1];
03424         mb.at(x, y).sliceIdx = biMv.sliceIdx;
03425       }
03426       else if (tpmMask == 0)
03427       {
03428         mb.at(x, y).isInter = true;
03429         mb.at(x, y).interDir = geoMrgCtx.interDirNeighbours[candIdx0];
03430         mb.at(x, y).refIdx[0] = geoMrgCtx.mvFieldNeighbours[candIdx0 << 1].refIdx;
03431         mb.at(x, y).refIdx[1] = geoMrgCtx.mvFieldNeighbours[(candIdx0 << 1) + 1].refIdx;
03432         mb.at(x, y).mv[0] = geoMrgCtx.mvFieldNeighbours[candIdx0 << 1].mv;
03433         mb.at(x, y).mv[1] = geoMrgCtx.mvFieldNeighbours[(candIdx0 << 1) + 1].mv;
03434         mb.at(x, y).sliceIdx = biMv.sliceIdx;
03435       }
03436       else
03437       {
03438         mb.at(x, y).isInter = true;
03439         mb.at(x, y).interDir = geoMrgCtx.interDirNeighbours[candIdx1];
03440         mb.at(x, y).refIdx[0] = geoMrgCtx.mvFieldNeighbours[candIdx1 << 1].refIdx;
03441         mb.at(x, y).refIdx[1] = geoMrgCtx.mvFieldNeighbours[(candIdx1 << 1) + 1].refIdx;
03442         mb.at(x, y).mv[0] = geoMrgCtx.mvFieldNeighbours[candIdx1 << 1].mv;
03443         mb.at(x, y).mv[1] = geoMrgCtx.mvFieldNeighbours[(candIdx1 << 1) + 1].mv;
03444         mb.at(x, y).sliceIdx = biMv.sliceIdx;
03445       }
03446     }
03447   }
03448 }
03449 
03450 bool CU::hasSubCUNonZeroMVd( const CodingUnit& cu )
03451 {
03452   bool bNonZeroMvd = false;
03453 
03454   for( const auto &pu : CU::traversePUs( cu ) )
03455   {
03456     if( ( !pu.mergeFlag ) && ( !cu.skip ) )
03457     {
03458       if( pu.interDir != 2 /* PRED_L1 */ )
03459       {
03460         bNonZeroMvd |= pu.mvd[REF_PIC_LIST_0].getHor() != 0;
03461         bNonZeroMvd |= pu.mvd[REF_PIC_LIST_0].getVer() != 0;
03462       }
03463       if( pu.interDir != 1 /* PRED_L0 */ )
03464       {
03465         if( !pu.cu->cs->picHeader->getMvdL1ZeroFlag() || pu.interDir != 3 /* PRED_BI */ )
03466         {
03467           bNonZeroMvd |= pu.mvd[REF_PIC_LIST_1].getHor() != 0;
03468           bNonZeroMvd |= pu.mvd[REF_PIC_LIST_1].getVer() != 0;
03469         }
03470       }
03471     }
03472   }
03473 
03474   return bNonZeroMvd;
03475 }
03476 
03477 bool CU::hasSubCUNonZeroAffineMVd( const CodingUnit& cu )
03478 {
03479   bool nonZeroAffineMvd = false;
03480 
03481   if ( !cu.affine || cu.firstPU->mergeFlag )
03482   {
03483     return false;
03484   }
03485 
03486   for ( const auto &pu : CU::traversePUs( cu ) )
03487   {
03488     if ( ( !pu.mergeFlag ) && ( !cu.skip ) )
03489     {
03490       if ( pu.interDir != 2 /* PRED_L1 */ )
03491       {
03492         for ( int i = 0; i < ( cu.affineType == AFFINEMODEL_6PARAM ? 3 : 2 ); i++ )
03493         {
03494           nonZeroAffineMvd |= pu.mvdAffi[REF_PIC_LIST_0][i].getHor() != 0;
03495           nonZeroAffineMvd |= pu.mvdAffi[REF_PIC_LIST_0][i].getVer() != 0;
03496         }
03497       }
03498 
03499       if ( pu.interDir != 1 /* PRED_L0 */ )
03500       {
03501         if ( !pu.cu->cs->picHeader->getMvdL1ZeroFlag() || pu.interDir != 3 /* PRED_BI */ )
03502         {
03503           for ( int i = 0; i < ( cu.affineType == AFFINEMODEL_6PARAM ? 3 : 2 ); i++ )
03504           {
03505             nonZeroAffineMvd |= pu.mvdAffi[REF_PIC_LIST_1][i].getHor() != 0;
03506             nonZeroAffineMvd |= pu.mvdAffi[REF_PIC_LIST_1][i].getVer() != 0;
03507           }
03508         }
03509       }
03510     }
03511   }
03512 
03513   return nonZeroAffineMvd;
03514 }
