03516 uint8_t CU::getSbtInfo( uint8_t idx, uint8_t pos )
03517 {
03518   return ( pos << 4 ) + ( idx << 0 );
03519 }
03520 
03521 uint8_t CU::getSbtIdx( const uint8_t sbtInfo )
03522 {
03523   return ( sbtInfo >> 0 ) & 0xf;
03524 }
03525 
03526 uint8_t CU::getSbtPos( const uint8_t sbtInfo )
03527 {
03528   return ( sbtInfo >> 4 ) & 0x3;
03529 }
03530 
03531 uint8_t CU::getSbtMode( uint8_t sbtIdx, uint8_t sbtPos )
03532 {
03533   uint8_t sbtMode = 0;
03534   switch( sbtIdx )
03535   {
03536   case SBT_VER_HALF: sbtMode = sbtPos + SBT_VER_H0;  break;
03537   case SBT_HOR_HALF: sbtMode = sbtPos + SBT_HOR_H0;  break;
03538   case SBT_VER_QUAD: sbtMode = sbtPos + SBT_VER_Q0;  break;
03539   case SBT_HOR_QUAD: sbtMode = sbtPos + SBT_HOR_Q0;  break;
03540   default:           assert( 0 );
03541   }
03542 
03543   assert( sbtMode < NUMBER_SBT_MODE );
03544   return sbtMode;
03545 }
03546 
03547 uint8_t CU::getSbtIdxFromSbtMode( uint8_t sbtMode )
03548 {
03549   if( sbtMode <= SBT_VER_H1 )
03550   {
03551     return SBT_VER_HALF;
03552   }
03553   else if( sbtMode <= SBT_HOR_H1 )
03554   {
03555     return SBT_HOR_HALF;
03556   }
03557   else if( sbtMode <= SBT_VER_Q1 )
03558   {
03559     return SBT_VER_QUAD;
03560   }
03561   else if( sbtMode <= SBT_HOR_Q1 )
03562   {
03563     return SBT_HOR_QUAD;
03564   }
03565   else
03566   {
03567     assert( 0 );
03568     return 0;
03569   }
03570 }
03571 
03572 uint8_t CU::getSbtPosFromSbtMode( uint8_t sbtMode )
03573 {
03574   if( sbtMode <= SBT_VER_H1 )
03575   {
03576     return sbtMode - SBT_VER_H0;
03577   }
03578   else if( sbtMode <= SBT_HOR_H1 )
03579   {
03580     return sbtMode - SBT_HOR_H0;
03581   }
03582   else if( sbtMode <= SBT_VER_Q1 )
03583   {
03584     return sbtMode - SBT_VER_Q0;
03585   }
03586   else if( sbtMode <= SBT_HOR_Q1 )
03587   {
03588     return sbtMode - SBT_HOR_Q0;
03589   }
03590   else
03591   {
03592     assert( 0 );
03593     return 0;
03594   }
03595 }
03596 
03597 uint8_t CU::targetSbtAllowed( uint8_t sbtIdx, uint8_t sbtAllowed )
03598 {
03599   uint8_t val = 0;
03600   switch( sbtIdx )
03601   {
03602   case SBT_VER_HALF: val = ( ( sbtAllowed >> SBT_VER_HALF ) & 0x1 ); break;
03603   case SBT_HOR_HALF: val = ( ( sbtAllowed >> SBT_HOR_HALF ) & 0x1 ); break;
03604   case SBT_VER_QUAD: val = ( ( sbtAllowed >> SBT_VER_QUAD ) & 0x1 ); break;
03605   case SBT_HOR_QUAD: val = ( ( sbtAllowed >> SBT_HOR_QUAD ) & 0x1 ); break;
03606   default:           CHECK( 1, "unknown SBT type" );
03607   }
03608   return val;
03609 }
03610 
03611 uint8_t CU::numSbtModeRdo( uint8_t sbtAllowed )
03612 {
03613   uint8_t num = 0;
03614   uint8_t sum = 0;
03615   num = targetSbtAllowed( SBT_VER_HALF, sbtAllowed ) + targetSbtAllowed( SBT_HOR_HALF, sbtAllowed );
03616   sum += std::min( SBT_NUM_RDO, ( num << 1 ) );
03617   num = targetSbtAllowed( SBT_VER_QUAD, sbtAllowed ) + targetSbtAllowed( SBT_HOR_QUAD, sbtAllowed );
03618   sum += std::min( SBT_NUM_RDO, ( num << 1 ) );
03619   return sum;
03620 }
03621 
03622 bool CU::isSbtMode( const uint8_t sbtInfo )
03623 {
03624   uint8_t sbtIdx = getSbtIdx( sbtInfo );
03625   return sbtIdx >= SBT_VER_HALF && sbtIdx <= SBT_HOR_QUAD;
03626 }
03627 
03628 bool CU::isSameSbtSize( const uint8_t sbtInfo1, const uint8_t sbtInfo2 )
03629 {
03630   uint8_t sbtIdx1 = getSbtIdxFromSbtMode( sbtInfo1 );
03631   uint8_t sbtIdx2 = getSbtIdxFromSbtMode( sbtInfo2 );
03632   if( sbtIdx1 == SBT_HOR_HALF || sbtIdx1 == SBT_VER_HALF )
03633   {
03634     return sbtIdx2 == SBT_HOR_HALF || sbtIdx2 == SBT_VER_HALF;
03635   }
03636   else if( sbtIdx1 == SBT_HOR_QUAD || sbtIdx1 == SBT_VER_QUAD )
03637   {
03638     return sbtIdx2 == SBT_HOR_QUAD || sbtIdx2 == SBT_VER_QUAD;
03639   }
03640   else
03641   {
03642     return false;
03643   }
03644 }
