03667 
03668 bool CU::isBcwIdxCoded( const CodingUnit &cu )
03669 {
03670   if( cu.cs->sps->getUseBcw() == false )
03671   {
03672     CHECK(cu.BcwIdx != BCW_DEFAULT, "Error: cu.BcwIdx != BCW_DEFAULT");
03673     return false;
03674   }
03675 
03676   if (cu.predMode == MODE_IBC)
03677   {
03678     return false;
03679   }
03680 
03681   if( cu.predMode == MODE_INTRA || cu.cs->slice->isInterP() )
03682   {
03683     return false;
03684   }
03685 
03686   if( cu.lwidth() * cu.lheight() < BCW_SIZE_CONSTRAINT )
03687   {
03688     return false;
03689   }
03690 
03691   if( !cu.firstPU->mergeFlag )
03692   {
03693     if( cu.firstPU->interDir == 3 )
03694     {
03695       const int refIdx0 = cu.firstPU->refIdx[REF_PIC_LIST_0];
03696       const int refIdx1 = cu.firstPU->refIdx[REF_PIC_LIST_1];
03697 
03698       const WPScalingParam *wp0 = cu.cs->slice->getWpScaling(REF_PIC_LIST_0, refIdx0);
03699       const WPScalingParam *wp1 = cu.cs->slice->getWpScaling(REF_PIC_LIST_1, refIdx1);
03700 
03701       return !(WPScalingParam::isWeighted(wp0) || WPScalingParam::isWeighted(wp1));
03702     }
03703   }
03704 
03705   return false;
03706 }
03707 
03708 uint8_t CU::getValidBcwIdx( const CodingUnit &cu )
03709 {
03710   if( cu.firstPU->interDir == 3 && !cu.firstPU->mergeFlag )
03711   {
03712     return cu.BcwIdx;
03713   }
03714   else if( cu.firstPU->interDir == 3 && cu.firstPU->mergeFlag && cu.firstPU->mergeType == MRG_TYPE_DEFAULT_N )
03715   {
03716     // This is intended to do nothing here.
03717   }
03718   else if( cu.firstPU->mergeFlag && cu.firstPU->mergeType == MRG_TYPE_SUBPU_ATMVP )
03719   {
03720     CHECK(cu.BcwIdx != BCW_DEFAULT, " cu.BcwIdx != BCW_DEFAULT ");
03721   }
03722   else
03723   {
03724     CHECK(cu.BcwIdx != BCW_DEFAULT, " cu.BcwIdx != BCW_DEFAULT ");
03725   }
03726 
03727   return BCW_DEFAULT;
03728 }
03729 
03730 void CU::setBcwIdx( CodingUnit &cu, uint8_t uh )
03731 {
03732   int8_t uhCnt = 0;
03733 
03734   if( cu.firstPU->interDir == 3 && !cu.firstPU->mergeFlag )
03735   {
03736     cu.BcwIdx = uh;
03737     ++uhCnt;
03738   }
03739   else if( cu.firstPU->interDir == 3 && cu.firstPU->mergeFlag && cu.firstPU->mergeType == MRG_TYPE_DEFAULT_N )
03740   {
03741     // This is intended to do nothing here.
03742   }
03743   else if( cu.firstPU->mergeFlag && cu.firstPU->mergeType == MRG_TYPE_SUBPU_ATMVP )
03744   {
03745     cu.BcwIdx = BCW_DEFAULT;
03746   }
03747   else
03748   {
03749     cu.BcwIdx = BCW_DEFAULT;
03750   }
03751 
03752   CHECK(uhCnt <= 0, " uhCnt <= 0 ");
03753 }
03754 
03755 uint8_t CU::deriveBcwIdx( uint8_t bcwLO, uint8_t bcwL1 )
03756 {
03757   if( bcwLO == bcwL1 )
03758   {
03759     return bcwLO;
03760   }
03761   const int8_t w0 = getBcwWeight(bcwLO, REF_PIC_LIST_0);
03762   const int8_t w1 = getBcwWeight(bcwL1, REF_PIC_LIST_1);
03763   const int8_t th = g_BcwWeightBase >> 1;
03764   const int8_t off = 1;
03765 
03766   if( w0 == w1 || (w0 < (th - off) && w1 < (th - off)) || (w0 >(th + off) && w1 >(th + off)) )
03767   {
03768     return BCW_DEFAULT;
03769   }
03770   else
03771   {
03772     if( w0 > w1 )
03773     {
03774       return ( w0 >= th ? bcwLO : bcwL1 );
03775     }
03776     else
03777     {
03778       return ( w1 >= th ? bcwL1 : bcwLO );
03779     }
03780   }
03781 }
