03783 bool CU::bdpcmAllowed( const CodingUnit& cu, const ComponentID compID )
03784 {
03785   SizeType transformSkipMaxSize = 1 << cu.cs->sps->getLog2MaxTransformSkipBlockSize();
03786 
03787   bool bdpcmAllowed = cu.cs->sps->getBDPCMEnabledFlag();
03788        bdpcmAllowed &= CU::isIntra( cu );
03789        if (isLuma(compID))
03790        {
03791          bdpcmAllowed &= (cu.lwidth() <= transformSkipMaxSize && cu.lheight() <= transformSkipMaxSize);
03792        }
03793        else
03794        {
03795          bdpcmAllowed &=
03796            (cu.chromaSize().width <= transformSkipMaxSize && cu.chromaSize().height <= transformSkipMaxSize)
03797            && !cu.colorTransform;
03798        }
03799   return bdpcmAllowed;
03800 }
03801 
03802 bool CU::isMTSAllowed(const CodingUnit &cu, const ComponentID compID)
03803 {
03804   SizeType tsMaxSize = 1 << cu.cs->sps->getLog2MaxTransformSkipBlockSize();
03805   const int maxSize  = CU::isIntra( cu ) ? MTS_INTRA_MAX_CU_SIZE : MTS_INTER_MAX_CU_SIZE;
03806   const int cuWidth  = cu.blocks[0].lumaSize().width;
03807   const int cuHeight = cu.blocks[0].lumaSize().height;
03808   bool mtsAllowed    = cu.chType == CHANNEL_TYPE_LUMA && compID == COMPONENT_Y;
03809 
03810   mtsAllowed &= CU::isIntra( cu ) ? cu.cs->sps->getUseIntraMTS() : cu.cs->sps->getUseInterMTS() && CU::isInter( cu );
03811   mtsAllowed &= cuWidth <= maxSize && cuHeight <= maxSize;
03812   mtsAllowed &= !cu.ispMode;
03813   mtsAllowed &= !cu.sbtInfo;
03814   mtsAllowed &= !(cu.bdpcmMode && cuWidth <= tsMaxSize && cuHeight <= tsMaxSize);
03815   return mtsAllowed;
03816 }
