03830 bool TU::getCbfAtDepth(const TransformUnit &tu, const ComponentID &compID, const unsigned &depth)
03831 {
03832   if( !tu.blocks[compID].valid() )
03833   {
03834     CHECK(tu.cbf[compID] != 0, "cbf must be 0 if the component is not available");
03835   }
03836   return ((tu.cbf[compID] >> depth) & 1) == 1;
