03839 void TU::setCbfAtDepth(TransformUnit &tu, const ComponentID &compID, const unsigned &depth, const bool &cbf)
03840 {
03841   // first clear the CBF at the depth
03842   tu.cbf[compID] &= ~(1  << depth);
03843   // then set the CBF
03844   tu.cbf[compID] |= ((cbf ? 1 : 0) << depth);
03845 }
