03847 bool TU::isTSAllowed(const TransformUnit &tu, const ComponentID compID)
03848 {
03849   const int maxSize = tu.cs->sps->getLog2MaxTransformSkipBlockSize();
03850 
03851   bool tsAllowed = tu.cs->sps->getTransformSkipEnabledFlag();
03852   tsAllowed &= ( !tu.cu->ispMode || !isLuma(compID) );
03853   SizeType transformSkipMaxSize = 1 << maxSize;
03854   tsAllowed &= !(tu.cu->bdpcmMode && isLuma(compID));
03855   tsAllowed &= !(tu.cu->bdpcmModeChroma && isChroma(compID));
03856   tsAllowed &= tu.blocks[compID].width <= transformSkipMaxSize && tu.blocks[compID].height <= transformSkipMaxSize;
03857   tsAllowed &= !tu.cu->sbtInfo;
03858 
03859   return tsAllowed;
03860 }
